def _normalize_cover_scene_brief(value: str, item: dict | None = None) -> str:
    """Persist a concise semantic scene, never the universal render contract."""
    fallback = " ".join(str((item or {}).get("title", "") or "").split()) or "current news topic"
    # Preserve V2 line structure until ``semantic_scene_brief`` has extracted
    # STORY CONTEXT; flattening first would make a legacy render payload look
    # like one huge, unusable scene.
    scene = semantic_scene_brief(value, fallback)
    if len(scene) > _COVER_SCENE_BRIEF_MAX_CHARS:
        raise ValueError(
            f"SCENE_BRIEF_TOO_LONG: визуальная сцена превышает {_COVER_SCENE_BRIEF_MAX_CHARS} символов; "
            "она не была молча обрезана"
        )
    return scene


def _normalize_cover_photo_prompt(value: str, item: dict | None = None) -> str:
    """Compatibility renderer for callers that explicitly need the V2 payload.

    New Cover rows must use :func:`_normalize_cover_scene_brief`; FastGen's
    render path and legacy-focused callers can continue to request V2 here.
    """
    return append_universal_thumbnail_core_v2(value, item)


def _cover_scene_tokens(value: object) -> set[str]:
    """Stable semantic evidence, intentionally blind to camera-only wording."""
    scene = semantic_scene_brief(value, "")
    words = re.findall(r"[A-Za-zА-Яа-яЁё0-9]+", scene.casefold())
    result: set[str] = set()
    for word in words:
        if (
            word in _COVER_SCENE_CAMERA_TOKENS
            or word in _COVER_SCENE_STOP_TOKENS
            or word in _COVER_SCENE_PRESENTATION_TOKENS
        ):
            continue
        # English inflection and Russian case endings should not make an
        # otherwise identical action look like a distinct visual event.
        if len(word) > 5:
            word = word[:5]
        result.add(word)
    return result


def _cover_scene_similarity(left: object, right: object) -> float:
    """Return deterministic lexical-semantic overlap for short scene briefs."""
    left_tokens = _cover_scene_tokens(left)
    right_tokens = _cover_scene_tokens(right)
    if not left_tokens or not right_tokens:
        return 0.0
    return len(left_tokens & right_tokens) / len(left_tokens | right_tokens)


def _cover_semantic_duplicate(candidate: object, prior: object) -> bool:
    """Reject camera-only and close paraphrase rewrites before they become active."""
    candidate_scene = semantic_scene_brief(candidate, "")
    prior_scene = semantic_scene_brief(prior, "")
    if not candidate_scene or not prior_scene:
        return False
    if _cover_prompt_key(candidate_scene) == _cover_prompt_key(prior_scene):
        return True
    # A high overlap after camera words are removed means the visible actors,
    # action and evidence are still the same scene, not a new strategy.
    return _cover_scene_similarity(candidate_scene, prior_scene) >= 0.72


def _cover_scene_is_grounded(scene: str, item: dict) -> tuple[bool, str]:
    """Keep high-risk visual event types inside the topic's supported evidence.

    This is a narrow factual safety check, not a topic router: it never picks a
    scene strategy or adds an event. It only rejects a provider's unsupported
    escalation before that scene can become durable state.
    """
    source = " ".join(str(item.get(key, "") or "") for key in (
        "title", "script", "topic", "event_context", "supporting_context", "main_consequence",
        "consequence", "conflict", "entities", "primary_entities",
    )).casefold()
    candidate = scene.casefold()
    for label, candidate_markers, support_markers in _COVER_SCENE_RISK_SUPPORT:
        if any(marker in candidate for marker in candidate_markers) and not any(marker in source for marker in support_markers):
            return False, label
    return True, ""


def _cover_distinct_prompt_options(
    options: list[str], _item: dict, avoided_options: list[object], *, scene_intensity: bool,
) -> list[str]:
    """Accept only distinct semantic scenes; never fake freshness with camera notes."""
    del scene_intensity
    result: list[str] = []
    for candidate in options:
        prior = [*avoided_options, *result]
        if any(_cover_semantic_duplicate(candidate, value) for value in prior):
            raise ValueError(
                "SEMANTIC_SCENE_DUPLICATE: новый visual brief повторяет активную, историческую "
                "или соседнюю сцену; камера или перефразировка не считаются новым сюжетом"
            )
        result.append(candidate)
    return result


def _cover_distinct_enhanced_rewrite_options(
    options: list[str], item: dict, previous_options: list[object],
) -> list[str]:
    """Compatibility entry point for the #297 enhanced duplicate contract."""
    return _cover_distinct_prompt_options(
        options, item, previous_options, scene_intensity=True,
    )


def _cover_news_conflict_requirement(item: dict) -> str:
    """Require a visible story stake without imposing a pre-classified scene."""
    del item
    return (
        "ОБЯЗАТЕЛЬНЫЙ ВИЗУАЛЬНЫЙ КОНФЛИКТ: сам найди в текущей теме главный конфликт, риск, изменение, реакцию или последствие "
        "и вырази его одним ясным визуальным столкновением. Не добавляй заранее заданные ракеты, разрушения, биржу, политиков, "
        "толпу или другой тип сцены только из-за категории новости; каждый такой элемент должен следовать из текущего контекста. "
    )


def _cover_instruction(item: dict, position: int, settings) -> str:
    title = str(item.get("title", "")).strip()
    excerpt = " ".join(str(item.get("script", "")).split())[:2000] if settings.cover_use_script_context else ""
    range_prompt = _cover_range_prompt(item, position, settings)
    # A saved legacy template is not an implicit provider instruction.  It is
    # only additive after the user deliberately enables their custom brief.
    base = range_prompt or (settings.cover_prompt_template if settings.cover_use_custom_prompt else "")
    request = (
        "Ты профессиональный арт-директор YouTube-обложек и планировщик новостной сцены. Верни только краткое, естественное английское "
        "описание фактов сцены: кто/что в кадре, видимое действие, материальные доказательства и среда. "
        "Сделай сцену максимально кликабельной за счёт ясного конфликта, ставки, реакции людей и одного мгновенно понятного визуального доказательства. "
        "Толпа, страх, военные, разрушения и последствия атаки допустимы только когда это подтверждено темой или сценарием. "
        "Не добавляй style prompt, photorealism, typography, headline/subheadline instructions, negative rules, "
        "устаревший шаблон, формат кадра или технические требования: их единожды добавит Final Prompt Builder. "
        "Верни JSON строго формата "
        '{"prompts":["..."],"recommended":1} без Markdown и пояснений. '
        f"Создай ровно {settings.cover_prompt_variant_count} разных semantic scene descriptions. "
        "Каждый вариант — короткий самостоятельный visual brief длиной 250–600 символов, максимум 800. "
        "Для вариантов выбирай разные ПОДТВЕРЖДЁННЫЕ темой visual strategies: ACTION, REACTION, CONSEQUENCE, CONFRONTATION, SCALE или EVIDENCE. "
        "Стратегию не подписывай отдельным ярлыком: покажи её самой видимой сценой. Не повторяй тот же сюжет перестановкой слов, "
        "ракурсом, дистанцией камеры, кадрированием или расположением объектов. Каждый вариант обязан передавать конкретное действие, "
        "визуальное доказательство и тему.\n\n"
        f"ТЕМА: {title}\n{_cover_structured_context(item)}\n{_cover_topic_visual_plan(item)}"
    )
    request += _cover_scene_intensity_instruction(settings)
    if base:
        request += f"\nДОПОЛНИТЕЛЬНЫЕ ТРЕБОВАНИЯ ПОЛЬЗОВАТЕЛЯ: {base}"
    request += _cover_ai_reference_instruction(item, position, settings)
    manual_face = Path(str(item.get("face_reference_path", "") or "")).expanduser()
    face_label = " ".join(str(item.get("face_reference_label", "") or "").split())
    if item.get("face_reference_source") == "manual" and manual_face.is_file() and face_label:
        request += (
            f"\nВЫБРАННОЕ ЛИЦО: «{face_label}». Это обязательный герой для новой обложки: "
            "подстрой сцену, свет и конфликт под эту персону; крупный портрет закрепи от нижнего края справа. "
            "Левая нижняя половина остаётся полностью свободной для слов. Не заменяй выбранного человека и не добавляй другого политика."
        )
    headline = " ".join(str(item.get("cover_headline", "")).split())
    subheadline = " ".join(str(item.get("cover_subheadline", "")).split())
    if headline:
        request += (
            f"\nВЫБРАННЫЕ СЛОВА ДЛЯ ОБЛОЖКИ: «{headline}». "
            "Построй визуальную композицию так, чтобы эта фраза была главным смысловым акцентом, "
            "и оставь под неё чистое контрастное место. Не рисуй буквы сам: текст будет наложен NewsFlow."
        )
    if subheadline:
        request += (
            f"\nВЫБРАННЫЙ ПОДЗАГОЛОВОК: «{subheadline}». "
            "Он уточняет главный текст: оставь рядом с заголовком место под строку меньшего размера. "
            "Не рисуй буквы сам: текст будет наложен NewsFlow."
        )
    if excerpt:
        request += f"\nКРАТКИЙ КОНТЕКСТ СЦЕНАРИЯ: {excerpt}"
    return request


def _migrate_legacy_cover_photo_prompts(settings: Settings) -> bool:
    """Keep approved legacy rows intact; V2 applies on explicit prompt generation.

    The render adapter still supplies V2 for an old scene, but a launch/snapshot
    must never rewrite a user's 84 persisted prompt choices in the background.
    """
    return False


def _cover_prompt_should_generate(item: dict, *, force: bool = False) -> bool:
    """Keep approved visual briefs unless the user explicitly asks for a rewrite."""
    if not str(item.get("title", "")).strip():
        return False
    if force:
        return True
    options = item.get("image_prompt_options")
    if isinstance(options, list) and any(str(value).strip() for value in options):
        return False
    return not str(item.get("image_prompt", "")).strip()


def _cover_text_revision(item: dict) -> str:
    """Identify the exact approved text pair used to plan a visual prompt."""
    values = [
        " ".join(str(item.get("cover_headline", "")).split()),
        " ".join(str(item.get("cover_subheadline", "")).split()),
    ]
    return hashlib.sha256(json.dumps(values, ensure_ascii=False).encode("utf-8")).hexdigest()[:16]


def _cover_prompt_revision(item: dict) -> str:
    prompt = " ".join(str(item.get("image_prompt", "")).split())
    return hashlib.sha256(prompt.encode("utf-8")).hexdigest()[:16] if prompt else ""


_COVER_PROMPT_HISTORY_LIMIT = 5


def _normalise_cover_prompt(value: object) -> str:
    """Canonical text for durable visual do-not-repeat evidence."""
    return " ".join(str(value or "").split())


def _cover_prompt_key(value: object) -> str:
    return _normalise_cover_prompt(value).casefold()


def _cover_active_prompt_options(item: dict) -> list[str]:
    """Return every active visual option, including legacy single-prompt rows."""
    values = item.get("image_prompt_options")
    candidates = list(values) if isinstance(values, list) else []
    candidates.append(item.get("image_prompt", ""))
    result: list[str] = []
    seen: set[str] = set()
    for value in candidates:
        prompt = _cover_scene_brief_for_memory(value)
        key = _cover_prompt_key(prompt)
        if prompt and key not in seen:
            result.append(prompt)
            seen.add(key)
    return result


def _cover_recent_prompt_history(item: dict) -> list[str]:
    """Read bounded durable history without reviving it as an active prompt."""
    values = item.get("recent_visual_prompt_history")
    if not isinstance(values, list):
        return []
    result: list[str] = []
    seen: set[str] = set()
    for value in values:
        prompt = _cover_scene_brief_for_memory(value)
        key = _cover_prompt_key(prompt)
        if prompt and key not in seen:
            result.append(prompt)
            seen.add(key)
    return result[-_COVER_PROMPT_HISTORY_LIMIT:]


def _remember_cover_prompt_history(item: dict, values: list[object]) -> None:
    """Append superseded active prompts to the row's small do-not-repeat window."""
    history = _cover_recent_prompt_history(item)
    for value in values:
        prompt = _cover_scene_brief_for_memory(value)
        key = _cover_prompt_key(prompt)
        if not prompt:
            continue
        history = [record for record in history if _cover_prompt_key(record) != key]
        history.append(prompt)
    if history:
        item["recent_visual_prompt_history"] = history[-_COVER_PROMPT_HISTORY_LIMIT:]


def _cover_scene_brief_for_memory(value: object) -> str:
    """Keep do-not-repeat evidence small even for an accepted legacy V2 row."""
    raw = str(value or "")
    if not raw.strip():
        return ""
    scene = semantic_scene_brief(raw, "")
    return scene if scene and len(scene) <= _COVER_SCENE_BRIEF_MAX_CHARS else ""


def _mark_cover_prompt_stale_for_current_text(item: dict) -> None:
    """Prevent a visual brief authored for old cover words from looking current."""
    has_prompt = bool(str(item.get("image_prompt", "")).strip() or item.get("image_prompt_options"))
    if has_prompt and item.get("prompt_text_signature") != _cover_text_revision(item):
        item.update(status="Промпты устарели", progress=0,
                    error="Текст обложки изменён: создайте новый визуальный промпт")


def _clean_cover_prompts(value: str, count: int) -> tuple[list[str], int]:
    text = str(value or "").strip()
    prompts: list[object] = []
    recommended = 1
    if "{" in text:
        try:
            parsed = json.loads(text[text.index("{"):text.rindex("}") + 1])
            if isinstance(parsed, dict):
                prompts = parsed.get("prompts") or [parsed.get("prompt", "")]
                recommended = int(parsed.get("recommended", 1) or 1)
        except (ValueError, TypeError, IndexError):
            pass
    if not prompts:
        prompts = [text]
    cleaned = []
    for raw in prompts:
        prompt = re.sub(r"^(?:prompt|промпт)\s*[:—-]\s*", "", str(raw), flags=re.IGNORECASE).strip()
        prompt = " ".join(prompt.split())
        if len(prompt) >= 35 and prompt not in cleaned:
            cleaned.append(prompt)
    if not cleaned:
        return [], 0
    return cleaned[:count], max(0, min(len(cleaned) - 1, recommended - 1))


def _cover_prompt_safety_blocked(error: object) -> bool:
    """Recognise provider content filters without hiding ordinary API failures."""
    text = str(error or "").casefold()
    return any(marker in text for marker in (
        "safety", "content filter", "policy", "request blocked", "blocked by provider", "unsafe",
    ))


def _fallback_cover_prompt(item: dict, variant: int = 0) -> str:
    """Create a deterministic, neutral visual prompt when an LLM filter blocks rewriting.

    This is deliberately a visual brief, not a claim that an incident happened. It lets
    the separate «Новые промпты» action finish and leaves image rendering to its own button.
    """
    title = " ".join(str(item.get("title", "")).split()) or "current news topic"
    context = " ".join(str(item.get("script", "")).split())[:500]
    del variant
    return (
        f"The visible event directly supported by {title}: show its main participant, action and strongest concrete evidence "
        "in the real setting stated by the current topic or script. "
        + (f"Current context: {context}." if context else "")
    )


def _cover_provider_error_message(error: object) -> str:
    """Keep operator-visible provider failures useful without persisting credentials."""
    message = " ".join(str(error or "Provider request failed").split())
    message = re.sub(r"\bsk-[A-Za-z0-9_-]+", "[REDACTED]", message)
    message = re.sub(r"(?i)\bbearer\s+\S+", "Bearer [REDACTED]", message)
    message = re.sub(
        r"(?i)\b(api[_ -]?key|authorization|token)\s*[:=]\s*[^\s,;]+",
        lambda match: f"{match.group(1)}=[REDACTED]",
        message,
    )
    return message[:500]


def _cover_text_provider_error_is_transient(error: object) -> bool:
    status_code = getattr(error, "status_code", None)
    if status_code == 429 or (isinstance(status_code, int) and 500 <= status_code <= 599):
        return True
    text = str(error or "").casefold()
    return any(marker in text for marker in (
        "winerror 10060", "timeout", "timed out", "connection", "network", "429",
        "500", "502", "503", "504", "temporar", "connection reset", "service unavailable",
    ))


class _BoundedCoverTextProvider:
    """Limit all real provider calls for one row/stage, including semantic repairs."""

    def __init__(self, pool: HybridTextPool, on_attempt) -> None:
        self.pool = pool
        self.on_attempt = on_attempt
        self.attempts = 0

    async def generate(self, prompt: str, **kwargs) -> str:
        while self.attempts < 4:
            self.attempts += 1
            self.on_attempt(self.attempts)
            try:
                return await self.pool.generate(prompt, **kwargs)
            except _BRIDGE_OPERATION_ERRORS as exc:
                if not _cover_text_provider_error_is_transient(exc) or self.attempts >= 4:
                    raise
                await asyncio.sleep(0)
        raise RuntimeError("Provider retry limit exhausted")


def _cover_prompt_provider_attempt(item: dict, attempt: int, settings: Settings, *, persist: bool) -> None:
    """Expose provider progress without persisting a staged fresh rewrite."""
    item.update(prompt_provider_attempt_count=attempt)
    _cover_step(
        item, "Повтор промпта" if attempt > 1 else "ИИ готовит промпт", 5,
        f"Попытка провайдера: {attempt}/4",
    )
    if persist:
        _save_cover_state(settings)


def generate_cover_prompts(payload: dict) -> dict:
    settings = load_settings()
    _hydrate_cover_library(settings)
    provider = str(payload.get("provider", settings.cover_prompt_provider)).strip().casefold()
    if provider not in {"agent", "openai"}:
        raise ValueError("Выберите «Агент NewsFlow» или «ChatGPT»")
    force = bool(payload.get("force") or payload.get("regenerate") or payload.get("replaceManual") or payload.get("rewrite"))
    scope = _current_cover_generation_scope(
        settings, payload, "Выберите хотя бы один сценарий для промптов обложек",
    )
    selected = [(index, item) for index, item in scope if _cover_prompt_should_generate(item, force=force)]
    if not selected:
        return _cover_noop_result(
            "cover-prompts", "Все выбранные промпты уже готовы; генерация не требуется.",
        )
    # Prompt rewriting should remain usable even when a text provider rejects a
    # violent-sounding phrase or no key is temporarily available. The fallback
    # is local and deterministic; it never starts image rendering.
    pool = None
    pool_error: Exception | None = None
    try:
        pool = HybridTextPool([], settings.openai_api_keys, "", settings.openai_model)
    except _BRIDGE_OPERATION_ERRORS as exc:
        pool_error = exc
    rewrite = bool(payload.get("rewrite"))
    # Fresh-prompt replacement has a stricter contract than ordinary
    # missing-only generation: it stages every provider result and does not
    # mutate the durable cover row until the replacement can be committed
    # together with invalidation of its old FastGen contract.
    stage_fresh_rewrite = bool(payload.get("_stage_fresh_prompt_rewrite"))
    staged: dict[int, dict] = {}
    staging_errors: dict[int, str] = {}
    if not stage_fresh_rewrite:
        settings.cover_prompt_provider = provider
        for _index, item in selected:
            _cover_step(item, "ИИ готовит промпт", 5)
            item.update(error="")
        _save_cover_state(settings)

    async def build_one(index: int, item: dict) -> None:
        # A shallow copy is sufficient: prompt construction writes only
        # scalar/list fields on the cover row, never nested source material.
        # It lets all provider/normalisation work happen without a visible
        # half-new prompt if this is a fresh replacement.
        target = dict(item) if stage_fresh_rewrite else item
        previous_options = _cover_active_prompt_options(item)
        recent_history = _cover_recent_prompt_history(item)
        do_not_repeat = list(previous_options)
        for value in recent_history:
            if _cover_prompt_key(value) not in {_cover_prompt_key(current) for current in do_not_repeat}:
                do_not_repeat.append(value)
        provider_call = _BoundedCoverTextProvider(
            pool,
            lambda attempt: _cover_prompt_provider_attempt(
                target, attempt, settings, persist=not stage_fresh_rewrite,
            ),
        )
        try:
            prompt = _cover_instruction(target, index, settings)
            if do_not_repeat:
                previous = "\n".join(f"- {value}" for value in do_not_repeat)
                prompt += (
                    "\nВИЗУАЛЬНЫЕ ВАРИАНТЫ, КОТОРЫЕ НЕЛЬЗЯ ПОВТОРЯТЬ: сделай новый визуальный ход, "
                    "заметно отличный от них, но сохрани фактическую тему и выбранные слова. "
                    "НЕ ПОВТОРЯЙ ни один вариант ниже.\nПРЕДЫДУЩИЕ ВАРИАНТЫ:\n" + previous
                )
            if provider == "agent":
                prompt = "Работай как специализированный агент NewsFlow. " + prompt
            if pool_error is not None:
                raise pool_error
            reference_paths = _cover_ai_reference_paths_for_item(target, index, settings)
            requested_count = max(1, int(settings.cover_prompt_variant_count or 1))

            async def request_scene_briefs(request: str) -> tuple[list[str], int]:
                generated, recommended = _clean_cover_prompts(
                    await provider_call.generate(request, image_paths=reference_paths[:6]), requested_count,
                )
                options = [_normalize_cover_scene_brief(value, target) for value in generated]
                if len(options) < requested_count:
                    raise ValueError(
                        "SEMANTIC_SCENE_VARIANTS_INCOMPLETE: ИИ не вернул требуемое число самостоятельных visual scenes"
                    )
                options = options[:requested_count]
                for option in options:
                    grounded, unsupported = _cover_scene_is_grounded(option, target)
                    if not grounded:
                        raise ValueError(
                            "UNSUPPORTED_SCENE_EVENT: visual brief добавил "
                            f"{unsupported}, хотя это не подтверждено текущей темой или сценарием"
                        )
                return (
                    _cover_distinct_prompt_options(
                        options, target, do_not_repeat, scene_intensity=settings.cover_scene_intensity_mode,
                    ),
                    recommended,
                )

            try:
                options, chosen = await request_scene_briefs(prompt)
            except ValueError as first_error:
                # A bounded repair asks for a genuinely different scene while
                # preserving the factual authority and every existing prompt.
                # It is not a camera-only local substitute and cannot mutate a
                # staged fresh rewrite before the semantic result is accepted.
                repair = (
                    f"{prompt}\n\nSEMANTIC REPAIR: предыдущий ответ не дал достаточного количества новых визуальных сцен "
                    f"({first_error}). Верни заново полный JSON. Выбери другой поддержанный темой visible strategy "
                    "(ACTION / REACTION / CONSEQUENCE / CONFRONTATION / SCALE / EVIDENCE), а не ту же сцену с новой камерой, "
                    "перефразировкой или перестановкой объектов."
                )
                options, chosen = await request_scene_briefs(repair)
            # An explicit terminal state lets the editor see that FastGen can
            # start; it is not merely an intermediate LLM progress label.
            _cover_step(target, "Промпты готовы", 100,
                        f"Подготовлено вариантов: {len(options)}")
            target.update(image_prompt_options=options, selected_prompt_index=chosen, image_prompt=options[chosen],
                          prompt_provider=provider, prompt_text_signature=_cover_text_revision(target), error="")
            target["prompt_revision_id"] = _cover_prompt_revision(target)
            if rewrite:
                _remember_cover_prompt_history(target, previous_options)
            if stage_fresh_rewrite:
                staged[index] = target
        except _BRIDGE_OPERATION_ERRORS as exc:
            if _cover_prompt_safety_blocked(exc):
                fallback_count = max(1, int(settings.cover_prompt_variant_count or 1))
                try:
                    options = [
                        _normalize_cover_scene_brief(_fallback_cover_prompt(target, variant), target)
                        for variant in range(fallback_count)
                    ]
                    options = _cover_distinct_prompt_options(
                        options, target, do_not_repeat, scene_intensity=settings.cover_scene_intensity_mode,
                    )
                except ValueError as fallback_error:
                    reason = _cover_provider_error_message(fallback_error)
                    _cover_step(target, "Ошибка промпта", 100, reason)
                    target.update(error=reason, prompt_provider_attempt_count=provider_call.attempts)
                    if stage_fresh_rewrite:
                        staging_errors[index] = reason
                else:
                    _cover_step(target, "Промпты готовы", 100,
                                "Провайдер отклонил формулировку: создан безопасный локальный вариант")
                    target.update(image_prompt_options=options, selected_prompt_index=0,
                                image_prompt=options[0], prompt_provider="local-fallback",
                                prompt_text_signature=_cover_text_revision(target), error="")
                    target["prompt_revision_id"] = _cover_prompt_revision(target)
                    if rewrite:
                        _remember_cover_prompt_history(target, previous_options)
                    if stage_fresh_rewrite:
                        staged[index] = target
            else:
                reason = _cover_provider_error_message(exc)
                _cover_step(target, "Ошибка промпта", 100, reason)
                target.update(error=reason, prompt_provider_attempt_count=provider_call.attempts)
                if stage_fresh_rewrite:
                    staging_errors[index] = reason
        if not stage_fresh_rewrite:
            _save_cover_state(settings)

    async def run_batch() -> None:
        # HybridTextPool owns two queue slots per active key.  Starting all
        # pending jobs lets it distribute work fairly while the pool itself
        # keeps the batch within that configured aggregate limit.
        await asyncio.gather(*(build_one(index, item) for index, item in selected))

    asyncio.run(run_batch())
    if stage_fresh_rewrite:
        return {"_fresh_prompt_staging": staged, "_fresh_prompt_errors": staging_errors}
    return snapshot()


