def _cover_word_structure_pair(item: dict, variation_index: int = 0) -> dict[str, object]:
    """Stable candidate ordering hint, never an editorial sentence template."""
    identity = str(item.get("production_item_id") or item.get("id") or item.get("title") or "cover")
    digest = int(hashlib.sha256(identity.casefold().encode("utf-8")).hexdigest()[:12], 16)
    variation = max(0, int(variation_index))
    h_id, h_role, h_slots = _COVER_WORD_HEADLINE_STRUCTURES[(digest + variation) % len(_COVER_WORD_HEADLINE_STRUCTURES)]
    candidates = _COVER_WORD_PAIRING[h_id]
    s_id = candidates[(digest // len(_COVER_WORD_HEADLINE_STRUCTURES) + variation) % len(candidates)]
    _, s_role, s_slots = next(row for row in _COVER_WORD_SUBHEADLINE_ROLES if row[0] == s_id)
    return {
        "headline_structure_id": h_id, "headline_structure": h_role, "headline_semantic_slots": list(h_slots),
        "subheadline_structure_id": s_id, "subheadline_structure": s_role, "subheadline_semantic_slots": list(s_slots),
    }


def _cover_word_should_generate(
    item: dict, kind: str, *, force: bool = False, replace_manual: bool = False,
) -> bool:
    prefix = "headline" if kind == "headline" else "subheadline"
    value_key = "cover_headline" if prefix == "headline" else "cover_subheadline"
    source = str(item.get(f"{prefix}_source", "")).upper()
    value = str(item.get(value_key, "")).strip()
    # A non-empty manual edit is an explicit operator override. Ordinary
    # retries/regeneration repair missing or AI-owned text only; replacement
    # must be opt-in through the dedicated replaceManual action.
    if source == "MANUAL" and value:
        return bool(replace_manual)
    # Clearing a manual value deliberately asks the missing-field repair path
    # to fill this field.  Its old MANUAL status must not make that blank field
    # permanently ineligible for normal generation.
    if not value:
        return True
    return bool(force)

def _cover_word_source_text(item: dict) -> str:
    fields = ("title", "topic", "angle", "event_context", "supporting_context", "script",
              "primary_entities", "primary_entity", "entities", "geography", "conflict",
              "main_consequence", "consequence", "framing")
    return " ".join(_cover_context_values(item.get(field)) for field in fields if item.get(field))


def _cover_word_semantic_plan(item: dict) -> dict[str, list[str]]:
    """Fact-only slots used before the visual prompt and FastGen stage."""
    source = _cover_word_source_text(item)
    values = list(dict.fromkeys(
        word.casefold() for word in re.findall(r"[A-Za-zА-Яа-яЁё0-9%-]{3,}", source)
        if word.casefold() not in _COVER_TOPIC_STOPWORDS
    ))
    slots = {name: [] for name in (
        "subject", "action", "object", "location", "cause", "conflict", "consequence",
        "stake", "second_side", "scale", "number", "surprise", "decision", "response",
        "affected_actor", "infrastructure", "risk", "next_step", "time", "economic",
        "security", "cost", "breakdown",
    )}
    lower = source.casefold()
    named_source_entities = _cover_word_named_source_entities(item)
    for word in values:
        if re.fullmatch(r"\d+(?:[.,]\d+)?%?", word):
            slots["number"].append(word)
        if word[:4] in named_source_entities:
            slots["subject"].append(word)
    geography_tokens = [
        word.casefold() for word in re.findall(
            r"[A-Za-zА-Яа-яЁё]{3,}", _cover_context_values(item.get("geography"))
        )
    ]
    slots["location"] = list(dict.fromkeys(geography_tokens))
    markers = {
        "action": ("заяв", "введ", "повыс", "закро", "перекр", "постав", "ответ", "переговор"),
        "object": ("нефт", "газ", "тариф", "экспорт", "порт", "термин", "постав", "санкц"),
        "cause": ("из-за", "потому", "после", "вследств"),
        "conflict": ("конфликт", "давлен", "санкц", "против", "спор", "эскалац"),
        "consequence": ("сократ", "рост", "паден", "риск", "потер", "дефиц"),
        "stake": ("цен", "рын", "безопас", "постав", "экспорт"),
        "infrastructure": ("порт", "термин", "труб", "завод", "систем", "инфраструкт"),
        "risk": ("может", "риск", "угроз", "вероят", "возмож"),
        "decision": ("решил", "решен", "введ", "одобр", "запрет"),
        "response": ("ответ", "реакц", "ответил"),
        "breakdown": ("сорва", "останов", "закро", "провал"),
    }
    for name, choices in markers.items():
        if any(choice in lower for choice in choices):
            slots[name] = values[:6]
    slots["economic"] = slots["object"] if any(x in lower for x in ("нефт", "газ", "тариф", "рын")) else []
    slots["security"] = slots["stake"] if any(x in lower for x in ("безопас", "военн", "атак", "угроз")) else []
    slots["cost"] = slots["stake"] if any(x in lower for x in ("цен", "потер", "стоим")) else []
    slots["second_side"] = slots["subject"][1:]
    slots["affected_actor"] = slots["subject"][:]
    slots["next_step"] = slots["action"][:]
    slots["scale"] = slots["number"][:]
    slots["surprise"] = slots["consequence"][:]
    return slots

def _cover_word_semantic_groups(value: str) -> set[str]:
    normalized = " ".join(str(value).casefold().split())
    return {name for name, markers in _COVER_WORD_SEMANTIC_GROUPS.items() if any(marker in normalized for marker in markers)}


def _cover_word_pattern_signature(value: str) -> str:
    """Stable semantic cooldown key, also recoverable from persisted text after restart."""
    groups = _cover_word_semantic_groups(value)
    if groups:
        return " ".join(sorted(groups))
    return " ".join(sorted(_cover_meaningful_word_stems(str(value)))[:2])


def _cover_word_foreign_entities(value: str, item: dict) -> set[str]:
    """Reject newly introduced proper names without any fixed name vocabulary."""
    source_tokens = {
        word.casefold()
        for word in re.findall(r"[A-Za-zА-Яа-яЁё]{3,}", _cover_word_source_text(item))
    }
    words = re.findall(r"[A-Za-zА-Яа-яЁё]{3,}", str(value))
    phrase_is_all_caps = bool(words) and all(word.isupper() for word in words)
    foreign: set[str] = set()
    for index, word in enumerate(words):
        lowered = word.casefold()
        if lowered in _COVER_WORD_GENERIC_ENTITY_TOKENS:
            continue
        looks_named = (not phrase_is_all_caps and index > 0 and word[:1].isupper())
        if not looks_named:
            continue
        if not any(
            lowered == source
            or (
                len(lowered) >= 4 and len(source) >= 4
                and (lowered.startswith(source) or source.startswith(lowered))
            )
            for source in source_tokens
        ):
            foreign.add(lowered)
    return foreign


def _cover_word_named_source_entities(item: dict) -> set[str]:
    """Return concrete entity anchors from the current ProductionItem only."""
    anchors: set[str] = set()

    def add_words(value: object, *, trust_structure: bool = False) -> None:
        text = _cover_context_values(value)
        for word in re.findall(r"[A-Za-zА-Яа-яЁё]{3,}", text):
            lowered = word.casefold()
            if lowered in _COVER_WORD_GENERIC_ENTITY_TOKENS:
                continue
            if trust_structure or word.isupper() or word[:1].isupper():
                anchors.add(lowered[:4])

    for field in ("primary_entities", "primary_entity", "entities", "geography", "selected_people"):
        if item.get(field):
            add_words(item.get(field), trust_structure=True)

    for field in ("direction", "topic", "title"):
        value = _cover_context_values(item.get(field))
        if not value:
            continue
        left = re.split(r"\s+[—–]\s+|\s+-\s+", value, maxsplit=1)[0]
        parts = [part.strip() for part in re.split(r"(?<!\s)[-–/](?!\s)", left) if part.strip()]
        if not parts:
            parts = [left]
        for part in parts:
            words = re.findall(r"[A-Za-zА-Яа-яЁё]{3,}", part)
            if words and all(word.isupper() or word[:1].isupper() for word in words):
                add_words(part)

    return anchors


def _cover_word_strengthens_source(value: str, item: dict) -> bool:
    """Detect materially stronger cover claims than the source carries."""
    phrase = " ".join(str(value or "").casefold().split())
    source = " ".join(_cover_word_source_text(item).casefold().split())
    # A universal quantifier must be supported for that object, not merely
    # occur somewhere in a source about another object (e.g. all shops).
    universal = r"\b(?:весь|вся|все|всё|всех|всего|всему|всю|целый|целая|целое|целые)\s+([а-яёa-z]{3,})"
    # "всё ещё" is an aspectual expression, not a claim about all objects.
    def affirmative_scope(text: str) -> set[str]:
        return {match[1][:4] for match in re.finditer(universal, text)
                if match[1] not in {"ещё", "еще"}
                and not re.search(r"\bне\s+$", text[:match.start()])}

    source_scope = affirmative_scope(source)
    if affirmative_scope(phrase) - source_scope:
        return True
    for output_markers, source_markers in _COVER_WORD_STRENGTHENING_RULES:
        if any(marker in phrase for marker in output_markers) and not any(
            marker in source for marker in source_markers
        ):
            return True
    return False


def _cover_word_subject_state_pass(value: str, item: dict) -> bool:
    """Conservative relation guard, not a blacklist of events or subjects.

    For compact prepositional states compare their grammatical bearer with
    the bearer of the same state in source clauses. Word presence alone is
    insufficient: an event cannot inherit its participant's state. Unknown
    constructions remain outside this bounded guard, not universal NLP claims.
    """
    text = value.casefold().rsplit(":", 1)[-1]
    match = re.search(r"\b(под|без)\s+([а-яёa-z]{4,})", text)
    source = ". ".join(_cover_word_source_text({key: value}).casefold()
                       for key, value in item.items() if value and _cover_word_source_text({key: value}))
    if not match:
        # Exact finite predicate in the source: preserve its grammatical
        # subject rather than promoting its object/modifier into the actor.
        # Unresolved morphology, passive/inverted and introductory clauses
        # stay outside this conservative local check.
        verbs = list(re.finditer(
            r"\b[а-яё]{3,}(?:ает|яет|еет|ует|ит|ят|ют|ил|ила|или|ал|ала|али|ыл|ыла|ыли|ется|ются)\b", text,
        ))
        for verb in verbs:
            subject = re.findall(r"[а-яёa-z]{3,}", text[:verb.start()])
            if not subject:
                continue
            subjects = set()
            for clause in re.split(r"[.!?;,:—–]|\s+-\s+", source):
                predicate = re.search(rf"\b{re.escape(verb[0])}\b", clause)
                if not predicate:
                    continue
                current_object = _cover_meaningful_word_stems(text[verb.end():])
                source_object = _cover_meaningful_word_stems(clause[predicate.end():])
                # Different complements may describe different supported
                # relations; only reject a demonstrable role transfer.
                if (current_object and source_object and not current_object & source_object
                        and subject[0][:4] not in source_object):
                    continue
                prefix = clause[:predicate.start()].strip()
                if re.search(r"\b(?:после|до|из-за|когда|если|согласно|перед|при|и)\b", prefix):
                    continue
                words = re.findall(r"[а-яёa-z]{3,}", prefix)
                # Attributive adjective, not a second political/person alias.
                if len(words) > 1 and re.search(r"(?:ский|ская|ские|ской|ная|ный|ное|ные)$", words[0]):
                    words = words[1:]
                if words and words[0] not in {"его", "ему", "её", "это", "они", "она", "оно"}:
                    structured_names = _cover_meaningful_word_stems(_cover_context_values(
                        item.get("primary_entities") or item.get("primary_entity") or item.get("entities")
                    ))
                    if subject[0][:4] in structured_names and words[0][:4] not in _cover_word_named_source_entities(item):
                        continue  # Anonymous source bearer with an explicit item-level name.
                    subjects.add(words[0][:4])
                    # An appositive name ("компания Lumira") belongs to the
                    # same subject; never take a prepositional object as it.
                    if not re.search(r"\b(?:на|для|от|с|у|о|об|в|по|из)\b", prefix):
                        subjects.update(word[:4] for word in words if word[:4] in _cover_word_named_source_entities(item))
            if subjects and subject[0][:4] not in subjects:
                return False
        return True
    subject_words = re.findall(r"[а-яёa-z]{3,}", text[:match.start()])
    if not subject_words:
        return True
    bearers: set[str] = set()
    # Split before extracting the bearer; a place/event in a previous clause
    # is not the subject of the current state. Keep genitive modifiers out.
    for clause in re.split(r"[.!?;,:—–]|\s+-\s+", source):
        state = re.search(rf"\b{match[1]}\s+{re.escape(match[2][:4])}[а-яёa-z]*", clause)
        if not state:
            continue
        prefix = clause[:state.start()]
        verbs = list(re.finditer(r"\b(?:отправ\w+|остав\w+|оста\w+|оказ\w+|наход\w+|попа\w+)\b", prefix))
        words = re.findall(r"[а-яёa-z]{3,}", prefix[verbs[-1].end():] if verbs and verbs[-1][0].startswith("отправ") else prefix)
        if words and words[0] not in {"его", "ему", "её", "это", "они", "она", "оно"}:
            bearers.add(words[0][:4])
        elif words and words[0] in {"его", "ему", "её"}:
            opening = re.findall(r"[а-яёa-z]{3,}", str(item.get("script", "")).casefold().split(".", 1)[0])
            if opening:
                bearers.add(opening[0][:4])
    if not bearers or subject_words[0][:4] in bearers:
        return True
    # An explicit pronominal continuation can retain the opening actor.
    # Do not infer aliases from a location/event appearing anywhere in title.
    clauses = re.split(r"[.!?;]", str(item.get("script", "")).casefold())
    if clauses and any(re.match(r"\s*(?:его|её|он|она|они)\b", clause) for clause in clauses[1:]):
        opening = re.findall(r"[а-яёa-z]{3,}", clauses[0])
        if opening and opening[0][:4] == subject_words[0][:4]:
            return True
    return False


def _cover_word_editorial_evaluation(
    value: str, item: dict, *, factual_pass: bool, grounding_pass: bool, duplicate_pass: bool,
) -> dict[str, object]:
    """Bounded local editorial rubric for one factual-safe thumbnail candidate.

    This is purposefully not a phrase blacklist.  It evaluates a candidate's
    relation to the current ProductionItem: content words must form a clear,
    source-grounded statement, and a novel invented verb/object pairing cannot
    become READY merely because the candidate mentions the right country.
    The persisted result is compact audit evidence, not model reasoning.
    """
    text = " ".join(str(value or "").casefold().split())
    words = re.findall(r"[A-Za-zА-Яа-яЁё]{3,}", text)
    stems = _cover_meaningful_word_stems(text)
    source_text = _cover_word_source_text(item)
    source_stems = _cover_meaningful_word_stems(source_text)
    source_words = set(re.findall(r"[A-Za-zА-Яа-яЁё]{3,}", source_text.casefold()))
    source_matches = {stem for stem in stems if stem in source_stems}
    unknown_stems = stems - source_stems
    # Finite verbs invented by the model are a reliable, context-independent
    # signal of an unsupported and often nonsensical subject/action pairing.
    # These are normal literal newsroom actions, not a negative phrase list.
    # A familiar newsroom verb is not automatically safe: the current source
    # must still support the action, and figurative pairings are rejected below.
    neutral_action_stems = {
        "обсуж", "повыш", "усил", "дави", "давл", "отвеч", "заяв", "ввод",
        "реша", "соглас", "отказ", "треб", "сниж", "раст", "постав", "закры",
    }
    explicit_action_stems = ("держ",)
    def supported_inflected_action(word: str) -> bool:
        # оплатить/оплачивать/платить: productive prefix and т/ч alternation.
        # This is source-dependent morphology, not a license for a familiar
        # financial action to appear without evidence.
        return bool(re.match(r"^(?:о|вы)?пла[тч]", word) and any(
            re.match(r"^(?:о|вы)?пла[тч]", source_word) for source_word in source_words
        ))

    unknown_action = any(
        (
            word[:4] in unknown_stems
            and not supported_inflected_action(word)
            and (
                word.startswith(explicit_action_stems)
                or (
                    not any(word.startswith(stem) for stem in neutral_action_stems)
                    and re.search(
                        r"(?:ает|яет|еет|ует|ит|ят|ют|ил|ила|или|ал|ала|али|"
                        r"ется|ются|ится|атся|ятся|лся|лась|лись|ался|алась|ались|ился|илась|ились)$",
                        word,
                    )
                )
            )
        )
        or (
            word.startswith(explicit_action_stems)
            and word not in source_words
        )
        for word in words
    )
    bare_abstract_state = (
        len(words) <= 3
        and "на" in text.split()
        and len(source_matches) < max(2, len(stems))
    )
    abstract_metaphor = (
        any(subject in text for subject in _COVER_WORD_ABSTRACT_METAPHOR_SUBJECTS)
        and any(action in text for action in _COVER_WORD_ABSTRACT_METAPHOR_ACTIONS)
    )
    market_metaphor = (
        any(subject in text for subject in _COVER_WORD_MARKET_METAPHOR_SUBJECTS)
        and any(action in text for action in _COVER_WORD_MARKET_METAPHOR_ACTIONS)
    )
    metaphorical_language = (
        any(marker in text for marker in _COVER_WORD_METAPHORICAL_MARKERS)
        or abstract_metaphor
        or market_metaphor
    )
    editorial_language = any(marker in text for marker in _COVER_WORD_EDITORIAL_MARKERS)
    incomplete_action = any(text.endswith(marker) for marker in _COVER_WORD_INCOMPLETE_ACTION_ENDINGS)
    list_like_nominal = (
        len(words) >= 3
        and " и " in f" {text} "
        and "?" not in text
        and not any(
            re.search(r"(?:ает|яет|еет|ует|ит|ят|ют|ил|ила|или|ал|ала|али|лся|лась|лись)$", word)
            for word in words
        )
    )
    negative_example_signal = any(pattern in text for pattern in _COVER_WORD_UNNATURAL_PATTERNS)
    # These quantities are deliberately finite and explainable rather than a
    # hidden chain of reasoning.  The known historical examples merely add a
    # weak signal; they cannot independently reject a phrase.
    plain_language_pass = not (
        metaphorical_language or editorial_language or incomplete_action or list_like_nominal
    )
    subject_state_pass = _cover_word_subject_state_pass(value, item)
    semantic_coherence_pass = not unknown_action and not bare_abstract_state and subject_state_pass
    literal_clarity_pass = not bare_abstract_state and bool(source_matches)
    naturalness_pass = semantic_coherence_pass and literal_clarity_pass and plain_language_pass
    cliche_penalty = int(negative_example_signal) + int(
        len(stems) > 0 and all(any(stem.startswith(generic) for generic in _COVER_WORD_GENERIC_STEMS)
                               for stem in stems)
    )
    named_anchors = _cover_word_named_source_entities(item)
    specificity_score = min(5, len(source_matches) + int(bool(stems & named_anchors)) + int(len(stems) >= 3))
    hook_markers = (
        "давл", "спор", "конфликт", "тариф", "санкц", "угроз", "рост", "паден", "усил",
        "закро", "переговор", "решен", "ответ", "атак", "удар", "арест", "протест",
        "отказ", "сорва", "потер", "дефиц", "цен",
    )
    emotion_markers = (
        "страх", "злост", "злит", "протест", "арест", "удар", "атак", "угроз",
        "потер", "сорва", "закро", "дорог", "цен", "сканд", "давл", "отказ",
    )
    hook_score = min(5, sum(any(stem.startswith(marker) or marker.startswith(stem)
                                for marker in hook_markers) for stem in stems))
    emotion_score = min(5, sum(any(stem.startswith(marker) or marker.startswith(stem)
                                   for marker in emotion_markers) for stem in stems))
    directness_score = min(
        5,
        len(source_matches)
        + int(bool(stems & named_anchors))
        + int(not metaphorical_language)
        + int(not editorial_language),
    )
    literal_matches = sum(word in source_words for word in words)
    literalness_score = int(100 * literal_matches / max(1, len(words)))
    # Historical negative examples raise an audit signal, but never form a
    # standalone rejection path.  The contextual coherence/clarity checks
    # above must independently explain why a phrase is unsuitable.
    editorial_plausibility_pass = naturalness_pass
    reasons: list[str] = []
    if unknown_action:
        reasons.append("unsourced_action_pairing")
    if not subject_state_pass:
        reasons.append("predicate_assigned_to_wrong_subject")
    if bare_abstract_state:
        reasons.append("unclear_abstract_state")
    if negative_example_signal:
        reasons.append("historical_negative_example_signal")
    if metaphorical_language:
        reasons.append("metaphorical_language")
    if editorial_language:
        reasons.append("editorial_column_language")
    if incomplete_action:
        reasons.append("incomplete_action")
    if list_like_nominal:
        reasons.append("list_like_nominal")
    if cliche_penalty and not negative_example_signal:
        reasons.append("generic_clickbait")
    if not naturalness_pass:
        reasons.append("naturalness_or_clarity_failed")
    return {
        "naturalness_pass": naturalness_pass,
        "semantic_coherence_pass": semantic_coherence_pass,
        "subject_state_pass": subject_state_pass,
        "literal_clarity_pass": literal_clarity_pass,
        "plain_language_pass": plain_language_pass,
        "cliche_penalty": cliche_penalty,
        "editorial_plausibility_pass": editorial_plausibility_pass,
        "specificity_score": specificity_score,
        "hook_score": hook_score,
        "emotion_score": emotion_score,
        "directness_score": directness_score,
        "literalness_score": literalness_score,
        "factual_pass": factual_pass,
        "grounding_pass": grounding_pass,
        "duplicate_pass": duplicate_pass,
        "quality_reasons": reasons,
    }


def _validate_cover_word(kind: str, value: str, item: dict, *, headline: str = "",
                         structure: dict | None = None, recent: list[dict] | None = None) -> dict[str, object]:
    """Return explicit validation/reason codes; never silently truncate into READY."""
    raw = str(value or "").strip()
    result = {"valid": False, "value": raw, "reason_code": "", "reason_detail": "", "semantic_slots": []}
    if not raw or raw.startswith((chr(96) * 3, "{")) or "\n" in raw:
        result.update(reason_code="INVALID_JSON", reason_detail="Ожидалось одно значение из JSON-ответа")
        return result
    words = raw.split()
    min_words, max_words, max_chars = (1, 5, 100) if kind == "headline" else (3, 10, 110)
    if len(raw) > max_chars:
        result.update(reason_code="TOO_LONG", reason_detail=f"Лимит: {max_chars} символов")
        return result
    if len(words) > max_words:
        result.update(reason_code="TOO_MANY_WORDS", reason_detail=f"Лимит: {max_words} слов")
        return result
    if len(words) < min_words:
        result.update(reason_code="TOO_SHORT", reason_detail=f"Нужно минимум {min_words} слов")
        return result
    if "!" in raw or (kind == "subheadline" and raw.isupper()):
        result.update(reason_code="STYLE_VIOLATION", reason_detail="Стиль строки не допускает это оформление")
        return result
    stems = _cover_meaningful_word_stems(raw)
    topic_stems = _cover_topic_terms(str(item.get("title", "")), _cover_word_source_text(item))
    if kind == "headline":
        named_source_entities = _cover_word_named_source_entities(item)
        phrase_tokens = {
            word[:4] for word in re.findall(r"[A-Za-zА-Яа-яЁё]{3,}", raw.casefold())
        }
        if named_source_entities and not (named_source_entities & phrase_tokens):
            result.update(
                reason_code="MISSING_NAMED_ANCHOR",
                reason_detail="Headline должен назвать конкретную сущность из темы, а не только действие или абстракцию",
            )
            return result
    # Existing topic terms keep five letters whereas duplicate detection uses
    # four-letter stems. Compare their shared stem instead of rejecting a
    # grounded inflection such as «экспорт» / «экспорта».
    if not any(word[:4] == topic[:4] for word in stems for topic in topic_stems):
        result.update(reason_code="NOT_GROUNDED", reason_detail="Нет значимой связи с темой или контекстом")
        return result
    foreign = _cover_word_foreign_entities(raw, item)
    if foreign:
        result.update(reason_code="FOREIGN_ENTITY", reason_detail=f"Чужие сущности: {', '.join(sorted(foreign))}")
        return result
    if stems and all(any(stem.startswith(generic) for generic in _COVER_WORD_GENERIC_STEMS) for stem in stems):
        result.update(reason_code="GENERIC_ONLY", reason_detail="Фраза состоит только из общего кликбейта")
        return result
    source = _cover_word_source_text(item).casefold()
    if _cover_word_strengthens_source(raw, item):
        result.update(
            reason_code="CLAIM_STRENGTH_ERROR",
            reason_detail="Строка усиливает действие или расширяет охват факта без подтверждения в теме или контексте",
        )
        return result
    if (any(token in raw.casefold() for token in _COVER_WORD_ASSERTIVE_TERMS)
            and any(token in source for token in _COVER_WORD_RISK_TERMS)
            and "?" not in raw
            and not any(token in raw.casefold() for token in ("может", "риск", "угроз"))):
        result.update(reason_code="CLAIM_STRENGTH_ERROR", reason_detail="Риск выдан за подтверждённый факт")
        return result
    if set(re.findall(r"\d+(?:[.,]\d+)?%?", raw)) - set(re.findall(r"\d+(?:[.,]\d+)?%?", source)):
        result.update(reason_code="UNSUPPORTED_FACT", reason_detail="В строку добавлено отсутствующее в источнике число")
        return result
    if kind == "subheadline" and headline:
        if _cover_lines_repeat_meaningful_words(headline, raw):
            result.update(reason_code="DUPLICATE_WORD", reason_detail="Повторяются содержательные слова headline")
            return result
        if _cover_word_semantic_groups(headline) & _cover_word_semantic_groups(raw):
            result.update(reason_code="DUPLICATE_MEANING", reason_detail="Вторая строка повторяет смысл headline")
            return result
    if recent:
        signature = _cover_word_pattern_signature(raw)
        recent_signatures = [
            str(row.get("pattern_signature") or _cover_word_pattern_signature(
                row.get("cover_headline") if kind == "headline" else row.get("cover_subheadline")
            ))
            for row in recent[-20:]
        ]
        if sum(1 for saved_signature in recent_signatures if saved_signature == signature) >= 3:
            result.update(reason_code="RECENT_PATTERN_REPEAT", reason_detail="Недавний паттерн использован слишком часто")
            return result
    evaluation = _cover_word_editorial_evaluation(
        raw, item, factual_pass=True, grounding_pass=True, duplicate_pass=True,
    )
    result["editorial_evaluation"] = evaluation
    if not (evaluation["naturalness_pass"] and evaluation["semantic_coherence_pass"]
            and evaluation["literal_clarity_pass"] and evaluation["editorial_plausibility_pass"]):
        result.update(
            reason_code="EDITORIAL_QUALITY_FAILED",
            reason_detail="Фраза не проходит контекстную редакторскую оценку естественности, ясности или сочетаемости",
        )
        return result
    result.update(valid=True, semantic_slots=list((structure or {}).get("semantic_slots", [])))
    return result

def _clean_cover_headline(value: str, *, emergency_limit: bool = True) -> str:
    text = str(value or "").strip()
    if "{" in text:
        try:
            parsed = json.loads(text[text.index("{"):text.rindex("}") + 1])
            if isinstance(parsed, dict):
                text = str(parsed.get("headline") or parsed.get("text") or "")
        except (ValueError, TypeError, IndexError):
            pass
    text = re.sub(r"^[\s\"'«»]+|[\s\"'«»]+$", "", text)
    # The cover headline stays compact but may include a necessary preposition
    # and object, e.g. «Трамп давит на Киев», without becoming a fragment.
    # Keep its hard rendering limit here as a final guard even if a provider
    # ignored the prompt constraint.
    words = text.split()
    return " ".join(words[:5] if emergency_limit else words)


def _clean_cover_subheadline(value: str) -> str:
    text = str(value or "").strip()
    if "{" in text:
        try:
            parsed = json.loads(text[text.index("{"):text.rindex("}") + 1])
            if isinstance(parsed, dict):
                text = str(parsed.get("subheadline") or parsed.get("subtitle") or parsed.get("text") or "")
        except (ValueError, TypeError, IndexError):
            pass
    text = re.sub(r"^[\s\"'«»]+|[\s\"'«»]+$", "", text)
    return " ".join(text.split())


_COVER_TOPIC_STOPWORDS = {
    "видео", "новости", "сегодня", "тема", "что", "когда", "почему", "который", "которое",
    "после", "перед", "через", "будет", "могут", "может", "самый", "новый", "новая",
    "главный", "снова", "теперь", "сила", "мир", "мировой", "мировая", "рынок", "рынки",
    "угроза", "угрозы", "ситуация", "ситуации", "влияние", "последствия", "демонстрирует",
}

# Prepositions and deliberately generic clickbait language may occur in both
# lines.  They do not make a thumbnail feel duplicated, unlike names, places,
# objects and verbs such as «Ормуз» / «нефтяники».
_COVER_LINE_STOPWORDS = _COVER_TOPIC_STOPWORDS | {
    "это", "этот", "эта", "эти", "как", "из", "для", "без", "над", "под", "при",
    "в", "во", "на", "за", "от", "до", "по", "у", "к", "с", "со", "и", "а", "но",
    "или", "ли", "уже", "ещё", "там", "здесь", "весь", "всё", "все", "свой",
}


def _cover_meaningful_word_stems(value: str) -> set[str]:
    """Use stems to catch obvious inflections: «нефть» / «нефтяников»."""
    return {
        word[:4] for word in re.findall(r"[A-Za-zА-Яа-яЁё]{4,}", str(value).casefold())
        if word not in _COVER_LINE_STOPWORDS
    }


def _cover_lines_repeat_meaningful_words(headline: str, subheadline: str) -> bool:
    return bool(_cover_meaningful_word_stems(headline) & _cover_meaningful_word_stems(subheadline))


# The two lines need distinct jobs.  We rotate structures deterministically by
# topic, so a batch is not filled with the same «X В ОГНЕ / X ...» pattern.
# These are writing constraints, not ready-made phrases, therefore examples
# from a user's style prompt still cannot leak into an unrelated news item.
_COVER_TEXT_STRUCTURES = (
    ("субъект или объект + конкретное действие", "последствие этого действия"),
    ("главная угроза или риск", "кто или что оказывается под давлением"),
    ("неожиданный поворот или конфликт", "конкретная ставка или цена этого поворота"),
    ("вопрос или интрига по факту темы", "короткий ответ-направление без повтора вопроса"),
    ("срочность или масштаб события", "отдельная деталь, объясняющая причину тревоги"),
    ("фигура или место из темы", "самостоятельное последствие для людей, рынков или безопасности"),
)


def _cover_text_structure(title: str) -> tuple[str, str]:
    normalized = "".join(str(title).casefold().split())
    return _COVER_TEXT_STRUCTURES[sum(map(ord, normalized)) % len(_COVER_TEXT_STRUCTURES)]


def _cover_topic_terms(title: str, context: str = "") -> set[str]:
    """Return distinctive topic stems that a cover phrase must reference.

    The user's examples may name unrelated politicians.  Requiring one of the
    actual scenario terms prevents such examples from becoming a result for a
    different topic while still allowing short, punchy thumbnail text.
    """
    terms: set[str] = set()
    # The title is deliberately weighted more strongly than the script: it is
    # the one thing that is always available for a manually imported topic.
    for word in re.findall(r"[A-Za-zА-Яа-яЁё]{4,}", f"{title} {title} {context}".casefold()):
        if word not in _COVER_TOPIC_STOPWORDS:
            terms.add(word[:5])
    return terms


def _cover_text_matches_topic(value: str, title: str, context: str = "", headline: str = "") -> bool:
    topic_terms = _cover_topic_terms(title, context)
    # A subheadline may also legitimately reference an already validated main
    # line, but cannot become a free-standing phrase about some other story.
    if headline:
        topic_terms |= _cover_topic_terms(headline)
    result_terms = {
        word[:5] for word in re.findall(r"[A-Za-zА-Яа-яЁё]{4,}", str(value).casefold())
        if word not in _COVER_TOPIC_STOPWORDS
    }
    return bool(topic_terms & result_terms)


def _migrate_legacy_cover_texts(settings: Settings) -> bool:
    """Move valid pre-2.1.50 suggestions into the visible text field once.

    Older builds wrote a generated phrase to ``*_suggestion`` and marked it as
    proposed.  The redesigned screen deliberately has no suggestion column,
    so leaving that hidden value in place made a completed generation look
    empty.  Invalid legacy suggestions are discarded instead of being shown
    under an unrelated scenario.
    """
    changed = False
    for item in settings.cover_queue:
        title = str(item.get("title", "")).strip()
        context = _scenario_context(item.get("script", ""))[:1300]
        legacy_headline = _clean_cover_headline(str(item.get("cover_headline_suggestion", "")))
        if not str(item.get("cover_headline", "")).strip() and legacy_headline:
            if _cover_text_matches_topic(legacy_headline, title, context):
                item.update(cover_headline=legacy_headline, headline_status="Заголовок готов", headline_error="")
            else:
                item.update(headline_status="Фраза отклонена: не по теме",
                            headline_error="Старая фраза ИИ не соответствовала сценарию и удалена")
            changed = True
        if item.pop("cover_headline_suggestion", None) is not None:
            changed = True
        legacy_subheadline = _clean_cover_subheadline(str(item.get("cover_subheadline_suggestion", "")))
        current_headline = str(item.get("cover_headline", ""))
        if not str(item.get("cover_subheadline", "")).strip() and legacy_subheadline:
            if _cover_text_matches_topic(legacy_subheadline, title, context, current_headline):
                item.update(cover_subheadline=legacy_subheadline, subheadline_status="Подзаголовок готов", subheadline_error="")
            else:
                item.update(subheadline_status="Подзаголовок отклонён: не по теме",
                            subheadline_error="Старая фраза ИИ не соответствовала сценарию и удалена")
            changed = True
        if item.pop("cover_subheadline_suggestion", None) is not None:
            changed = True
        # A completed IPC command never legitimately leaves a preparation
        # status.  Mark a crashed old request explicitly so it can be retried.
        if (not str(item.get("cover_headline", "")).strip()
                and str(item.get("headline_status", "")).startswith("Фраза:")):
            item.update(headline_status="Ошибка фразы", headline_error="Старый запрос не сохранил результат; перегенерируйте заголовок")
            changed = True
    return changed


def _cover_word_provider_prompt(kind: str, template: str, item: dict, structure: dict[str, object],
                                headline: str = "", *, tabloid_mode: bool = False) -> str:
    """Strict V2 provider prompt; visual generation remains outside this layer."""
    title = str(item.get("title", "")).strip()
    context = _cover_word_source_text(item)[:4000]
    plan = _cover_word_semantic_plan(item)
    source_template = template.replace("{title}", title).replace("{excerpt}", context)
    prefix = "headline" if kind == "headline" else "subheadline"
    role = structure[f"{prefix}_structure"]
    slots = structure[f"{prefix}_semantic_slots"]
    schema = (
        '{"headline":"...", "candidates":["...","...","...","..."]}'
        if kind == "headline" else
        '{"subheadline":"...", "candidates":["...","...","...","..."]}'
    )
    target = "1–5 слов, максимум 5 слов и 100 символов" if kind == "headline" else "3–7 слов, максимум 10 слов и 110 символов"
    task = (
        "Ты создаёшь только одну строку для новостной YouTube-обложки. "
        "Примеры пользовательского стиля не являются фактами и не могут переносить чужие имена, страны или события. "
        f"ТЕМА: «{title}». КОНТЕКСТ: «{context}». ДОСТУПНЫЕ СЕМАНТИЧЕСКИЕ СЛОТЫ: {json.dumps(plan, ensure_ascii=False)}. "
        f"ПОЛЬЗОВАТЕЛЬСКИЙ STYLE TEMPLATE: {source_template}. "
        f"РЕДАКЦИОННОЕ НАПРАВЛЕНИЕ: {role}. ПРЕДПОЧТИТЕЛЬНЫЕ СЛОТЫ: {', '.join(slots)}. "
        "Это направление не является обязательным шаблоном: сначала найди естественный subject/action/conflict/stake, "
        "затем предложи разные короткие варианты. Верни 4–6 кандидатов, а не один случайный hash-шаблон. "
    )
    task += (
        "СТИЛЬ: TABLOID. Пиши ещё жёстче, эмоциональнее и грязнее по подаче, чем STANDARD: выноси вперёд "
        "подтверждённый конфликт, провал, потерю, страх, злость, давление, ответственность, цену или неприятное "
        "последствие. Используй простые массовые слова и прямой разговорный русский, который мгновенно читается "
        "на YouTube-обложке. Грязнее означает выбрать самый острый ПОДТВЕРЖДЁННЫЙ угол, а не придумать обвинение. "
        "Стиль не литературный и не газетный. Никаких метафор, образных глаголов, литературных оборотов, "
        "газетно-колоночного или политологического языка. "
        "Не добавляй фактов, чисел, угроз, ультиматумов, действий или сущностей, которых нет в источнике. "
        if tabloid_mode else
        "СТИЛЬ: STANDARD. Пиши живо, эмоционально и цепко, но буквально: простой современный разговорный русский, "
        "конкретный subject/action/stake и понятный hook. Стиль не литературный и не газетный: не пиши как "
        "газетная колонка, аналитик или литератор. "
        "Никаких метафор, образных глаголов, политологической абстракции и красивых формулировок ради красоты. "
    )
    if kind == "headline":
        task += (
            "Headline обязан быть самодостаточным: без полного названия ролика зритель сразу должен понимать, "
            "кто или что находится в центре конфликта. Если в теме назван человек, страна, город или организация, "
            "включи хотя бы одну такую конкретную сущность в headline. Запрещены голые действия и абстрактные "
            "пары без субъекта — например «Не уступает» и «Новые условия». "
            "Не усиливай исходное действие: если тема говорит «не уступает», не заменяй это на «бросил вызов», "
            "ультиматум, угрозу или другое более жёсткое утверждение, которого в источнике нет. "
            "При равной фактической точности выбери наиболее кликабельный hook: конкретный конфликт, сильное действие, "
            "угрозу, ставку или неожиданный поворот. Не выбирай скучную нейтральную формулировку, если её можно "
            "точнее и сильнее выразить без изменения фактов. Не используй пустой общий кликбейт. "
        )
    else:
        task += (
            f"УЖЕ УТВЕРЖДЁННЫЙ HEADLINE: «{headline}». "
            "Главная строка уже является hook. Добавь второй самостоятельный информационный слой: другую причину, "
            "последствие, ставку, объект, место, действие или сторону. Не перефразируй headline и не повторяй его смысл. "
        )
    return (
        task + f"Требование длины каждого кандидата: {target}. Не придумывай числа и не усиливай риск до факта. "
        "Главное правило языка: максимально естественно, просто и прямо. Не заменяй событие авторской интерпретацией. "
        "Предпочитай буквальный сильный глагол или конкретное последствие вместо метафоры. Без канцелярита, "
        "газетных штампов, редкой книжной лексики, политологического жаргона, странных глаголов с объектом и "
        "метафор ради драмы. Не используй лишние кавычки, Markdown или комментарии. Верни строго только JSON: " + schema
    )


def _cover_word_repair_prompt(kind: str, value: str, validation: dict[str, object], item: dict,
                              structure: dict[str, object], headline: str = "", *, tabloid_mode: bool = False) -> str:
    prefix = "headline" if kind == "headline" else "subheadline"
    next_pair = _cover_word_structure_pair(item, int(item.get(f"{prefix}_variation_index", 0) or 0) + 1)
    return (
        f"Предыдущая строка «{value or 'пусто'}» отклонена. REASON: {validation['reason_code']}. "
        f"DETAIL: {validation['reason_detail']}. Исправь только эту проблему, не выдумывай новых фактов и не копируй "
        "предыдущую фразу. "
        + _cover_word_provider_prompt(kind, "", item, next_pair, headline, tabloid_mode=tabloid_mode)
    )


def _cover_word_candidates(raw: str, kind: str) -> list[str]:
    """Read a candidate batch while remaining compatible with old one-value providers."""
    text = str(raw or "").strip()
    parsed = None
    try:
        parsed = json.loads(text[text.index("{"):text.rindex("}") + 1])
    except (ValueError, TypeError, IndexError, json.JSONDecodeError):
        pass
    values: list[object] = []
    if isinstance(parsed, dict):
        values = parsed.get("candidates") if isinstance(parsed.get("candidates"), list) else [
            parsed.get(kind), parsed.get("text"), parsed.get("headline" if kind == "headline" else "subheadline"),
        ]
    else:
        values = [text]
    cleaner = _clean_cover_headline if kind == "headline" else _clean_cover_subheadline
    return list(dict.fromkeys(value for value in (cleaner(str(value), emergency_limit=False)
                                                  if kind == "headline" else cleaner(str(value))
                                                  for value in values if isinstance(value, str)) if value))


def _cover_word_candidate_score(value: str, item: dict) -> tuple[int, int, int]:
    """Compatibility wrapper for callers that only need a stable source score."""
    source = _cover_word_source_text(item).casefold()
    anchors = _cover_word_named_source_entities(item)
    terms = {word[:4] for word in re.findall(r"[A-Za-zА-Яа-яЁё]{3,}", value.casefold())}
    return (int(bool(terms & anchors)), sum(term in source for term in terms), -len(value))


def _cover_word_editorial_selection_score(
    value: str, validation: dict[str, object], *, tabloid_mode: bool,
) -> tuple[int, ...]:
    """Select only from validated candidates using persisted editorial evidence."""
    evaluation = validation.get("editorial_evaluation")
    if not isinstance(evaluation, dict):
        return (0, 0, 0, 0, -len(value))
    natural = int(bool(evaluation.get("naturalness_pass")))
    factual = int(bool(evaluation.get("factual_pass")))
    specificity = int(evaluation.get("specificity_score", 0) or 0)
    hook = int(evaluation.get("hook_score", 0) or 0)
    emotion = int(evaluation.get("emotion_score", 0) or 0)
    directness = int(evaluation.get("directness_score", 0) or 0)
    literalness = int(evaluation.get("literalness_score", 0) or 0)
    # Safety and literal source support precede the style preference in BOTH
    # modes. Emotion cannot buy weaker grounding or semantic coherence.
    quality = (
        factual, int(bool(evaluation.get("grounding_pass"))), natural,
        int(bool(evaluation.get("semantic_coherence_pass"))),
        int(bool(evaluation.get("literal_clarity_pass"))), specificity, literalness,
    )
    return (
        (*quality, hook, emotion, directness, -len(value))
        if tabloid_mode else
        (*quality, directness, -len(value))
    )


def _select_cover_word_candidate(
    accepted: list[tuple[str, dict[str, object]]], *, tabloid_mode: bool,
) -> tuple[str, dict[str, object]]:
    """Compare TABLOID to the safe STANDARD baseline of this same batch.

    No extra generation. A material gain requires at least one rubric point
    in hook/emotion/directness, with no loss in the other two or any safety
    score. A different spelling alone is never advertised as enhancement.
    """
    baseline = max(accepted, key=lambda pair: _cover_word_editorial_selection_score(
        pair[0], pair[1], tabloid_mode=False,
    ))
    baseline_eval = baseline[1]["editorial_evaluation"]
    strength_keys = ("hook_score", "emotion_score", "directness_score")
    quality_keys = ("factual_pass", "grounding_pass", "naturalness_pass", "semantic_coherence_pass",
                    "literal_clarity_pass", "specificity_score", "literalness_score")
    stronger = [pair for pair in accepted if pair[0] != baseline[0]
                and all(pair[1]["editorial_evaluation"].get(key, 0) >= baseline_eval.get(key, 0)
                        for key in (*quality_keys, *strength_keys))
                and any(pair[1]["editorial_evaluation"].get(key, 0) > baseline_eval.get(key, 0)
                        for key in strength_keys)]
    selected = max(stronger, key=lambda pair: _cover_word_editorial_selection_score(
        pair[0], pair[1], tabloid_mode=True,
    )) if tabloid_mode and stronger else baseline
    value, validation = selected
    validation = dict(validation)
    evidence = dict(validation["editorial_evaluation"])
    differentiated = bool(tabloid_mode and stronger)
    validation.update(
        selection_reason=("materially stronger grounded tabloid hook than safe standard baseline" if differentiated
                          else "tabloid differentiation unavailable; safe standard result" if tabloid_mode
                          else "best direct standard candidate after editorial quality evaluation"),
        selection_evidence={
            "style": "TABLOID" if tabloid_mode else "STANDARD",
            **{key: evidence.get(key, 0) for key in (*quality_keys, *strength_keys)},
            "tabloid_differentiation": "AVAILABLE" if differentiated else "UNAVAILABLE" if tabloid_mode else "NOT_REQUESTED",
            "degraded_result": bool(tabloid_mode and not differentiated),
            "standard_baseline": baseline[0],
        },
    )
    return value, validation


def _cover_word_source_fallback(
    kind: str,
    item: dict,
    *,
    headline: str = "",
    structure: dict[str, object] | None = None,
    recent: list[dict] | None = None,
    tabloid_mode: bool = False,
) -> tuple[str, dict[str, object]] | None:
    """Build one local grounded fallback without another provider request.

    Source-title segments are preferred.  If none is usable, a deliberately
    plain "<anchor>: what happened/is known" form keeps the row non-empty while
    making no new factual claim.
    """
    title = " ".join(str(item.get("title", "") or "").split())
    segments = [
        re.sub(r"^[\s«»\"'—–-]+|[\s«»\"'—–-]+$", "", part).strip()
        for part in re.split(r"\s+[—–]\s+|\s+-\s+|(?<=[.!?])\s+", title)
    ]
    max_words = 5 if kind == "headline" else 10
    min_words = 1 if kind == "headline" else 3
    candidates = [
        part for part in segments
        if min_words <= len(part.split()) <= max_words
    ]

    title_words = [
        word for word in re.findall(r"[A-Za-zА-Яа-яЁё]{4,}", title)
        if word.casefold() not in _COVER_TOPIC_STOPWORDS
    ]
    headline_stems = _cover_meaningful_word_stems(headline)
    named = _cover_word_named_source_entities(item)
    ordered_words = sorted(
        dict.fromkeys(title_words),
        key=lambda word: (word.casefold()[:4] not in named, title_words.index(word)),
    )
    if kind == "headline":
        if ordered_words:
            candidates.append(f"{ordered_words[0]}: что произошло?")
    else:
        second_anchor = next(
            (word for word in ordered_words if word.casefold()[:4] not in headline_stems),
            "",
        )
        if second_anchor:
            candidates.append(f"{second_anchor}: что известно сейчас")

    validated: list[tuple[str, dict[str, object]]] = []
    for candidate in dict.fromkeys(candidates):
        validation = _validate_cover_word(
            kind,
            candidate,
            item,
            headline=headline,
            structure={"semantic_slots": list((structure or {}).get(f"{kind}_semantic_slots", []))},
            recent=recent,
        )
        if validation["valid"]:
            validated.append((candidate, validation))
    if not validated:
        return None
    # Title segments are already ordered by editorial importance; for a
    # fail-soft path prefer the first valid source phrase over inventing a
    # stronger local rewrite.
    return validated[0]


async def _generate_cover_word_v2(pool: HybridTextPool, kind: str, item: dict, template: str,
                                  structure: dict[str, object], *, headline: str = "",
                                  pause_waiter=None, recent: list[dict] | None = None,
                                  tabloid_mode: bool = False) -> tuple[str, dict[str, object], list[dict]]:
    """Generate, validate and repair at most twice; callers persist state per item."""
    prompt = _cover_word_provider_prompt(kind, template, item, structure, headline, tabloid_mode=tabloid_mode)
    attempts: list[dict] = []
    for repair_index in range(2):
        raw = await pool.generate(prompt, before_request=pause_waiter)
        accepted: list[tuple[str, dict[str, object]]] = []
        for candidate in _cover_word_candidates(raw, kind):
            validation = _validate_cover_word(
                kind, candidate, item, headline=headline,
                structure={"semantic_slots": structure[f"{kind}_semantic_slots"]}, recent=recent,
            )
            attempts.append({"attempt": repair_index, "value": candidate, "validation": validation})
            if validation["valid"]:
                accepted.append((candidate, validation))
        if accepted:
            value, validation = _select_cover_word_candidate(accepted, tabloid_mode=tabloid_mode)
            validation["candidate_count"] = len(_cover_word_candidates(raw, kind))
            return value, validation, attempts
        if repair_index == 1:
            break
        last = attempts[-1]["validation"] if attempts else {"reason_code": "INVALID_JSON", "reason_detail": "Пустой ответ"}
        prompt = _cover_word_repair_prompt(kind, "", last, item, structure, headline, tabloid_mode=tabloid_mode)
    fallback = _cover_word_source_fallback(
        kind,
        item,
        headline=headline,
        structure=structure,
        recent=recent,
        tabloid_mode=tabloid_mode,
    )
    if fallback is not None:
        value, validation = fallback
        validation = dict(validation)
        evidence = dict(validation.get("editorial_evaluation", {}))
        validation.update(
            candidate_count=len(attempts),
            selection_reason=("safe grounded local fallback after bounded editorial repairs"
                              + ("; tabloid differentiation unavailable" if tabloid_mode else "")),
            selection_evidence={
                "style": "TABLOID" if tabloid_mode else "STANDARD",
                "fallback": True,
                "tabloid_differentiation": "UNAVAILABLE" if tabloid_mode else "NOT_REQUESTED",
                "degraded_result": tabloid_mode,
                "naturalness_pass": bool(evidence.get("naturalness_pass")),
                "specificity_score": int(evidence.get("specificity_score", 0) or 0),
                "hook_score": int(evidence.get("hook_score", 0) or 0),
                "emotion_score": int(evidence.get("emotion_score", 0) or 0),
                "directness_score": int(evidence.get("directness_score", 0) or 0),
                "literalness_score": int(evidence.get("literalness_score", 0) or 0),
                "factual_pass": bool(evidence.get("factual_pass")),
            },
        )
        return value, validation, attempts
    final_validation = attempts[-1]["validation"] if attempts else {
        "reason_code": "INVALID_JSON", "reason_detail": "Провайдер не вернул кандидатов",
    }
    raise ValueError(f"{final_validation['reason_code']}: {final_validation['reason_detail']}")


def _cover_text_prompt(kind: str, template: str, title: str, context: str, headline: str = "",
                       use_structure: bool = True, avoid_repeats: bool = True) -> str:
    """Build a topic-locked prompt for either cover text line."""
    style = template.replace("{title}", title).replace("{excerpt}", context)
    response_schema = '{"headline":"1–5 слов"}' if kind == "headline" else '{"subheadline":"2–7 слов"}'
    base = (
        "Ты создаёшь только текст одной новостной YouTube-обложки.\n"
        "НИЖЕ ПОЛЬЗОВАТЕЛЬСКИЕ ПРАВИЛА СТИЛЯ. Примеры в них — не факты, не готовые фразы и не имена, "
        "их нельзя дословно переносить в ответ:\n"
        f"---\n{style}\n---\n"
        f"ЕДИНСТВЕННАЯ ТЕМА: «{title}».\n"
        f"КОНТЕКСТ ЭТОЙ ТЕМЫ: «{context or 'не указан'}».\n"
    )
    if headline:
        base += f"ГЛАВНАЯ СТРОКА ЭТОЙ ЖЕ ОБЛОЖКИ: «{headline}».\n"
    base += (
        "Ответ обязан прямо содержать хотя бы одно ключевое слово, имя, страну, место или объект из темы выше. "
        "Нельзя подставлять Алиева, Зеленского, другого политика, другую страну или событие, если их нет в теме/контексте. "
        "Нельзя выдавать домысел за подтверждённый факт. "
    )
    headline_structure, subheadline_structure = _cover_text_structure(title)
    if kind == "headline" and use_structure:
        base += (
            f"СТРУКТУРА ГЛАВНОЙ СТРОКИ ДЛЯ ЭТОЙ ТЕМЫ: {headline_structure}. "
            "Не пересказывай заголовок ролика дословно. "
        )
    if kind == "subheadline":
        base += (
            "Вторая строка должна дополнять главную. "
        )
        if avoid_repeats:
            base += (
                "Нельзя повторять ни одно содержательное слово или его форму из главной строки "
                "(например, «ОРМУЗ» и «Ормуз», «нефть» и «нефтяников»). "
                "Возьми другую сущность, действие или последствие строго из темы/контекста. "
            )
        if use_structure:
            base += f"СТРУКТУРА ВТОРОЙ СТРОКИ ДЛЯ ЭТОЙ ТЕМЫ: {subheadline_structure}. "
    base += f"Верни только JSON: {response_schema}. Без пояснений, Markdown и вариантов."
    return base


def _generate_topic_locked_cover_text(pool: HybridTextPool, prompt: str, cleaner, title: str,
                                      context: str, headline: str = "", pause_waiter=None,
                                      avoid_repeats: bool = True) -> str:
    """Ask once more if the model ignored the scenario and copied an example."""
    return asyncio.run(_generate_topic_locked_cover_text_async(pool, prompt, cleaner, title, context, headline, pause_waiter, avoid_repeats))


async def _generate_topic_locked_cover_text_async(pool: HybridTextPool, prompt: str, cleaner, title: str,
                                                  context: str, headline: str = "", pause_waiter=None,
                                                  avoid_repeats: bool = True) -> str:
    """Topic validation that can share one two-slots-per-key pool across a batch."""
    result = cleaner(await pool.generate(prompt, before_request=pause_waiter))
    topic_matches = _cover_text_matches_topic(result, title, context, headline)
    repeats_headline = bool(avoid_repeats and headline and _cover_lines_repeat_meaningful_words(headline, result))
    if topic_matches and not repeats_headline:
        return result
    reason = (
        f"он повторяет значимые слова из главной строки «{headline}»"
        if repeats_headline else f"он не связан с темой «{title}»"
    )
    repair = (
        f"Предыдущий вариант «{result or 'пусто'}» отклонён: {reason}.\n"
        "Исправь его. Используй только сущности и смысл указанной темы, не используй примеры из стилевого промпта. "
        + ("Для второй строки используй другие смысловые слова, а не вариацию главной строки.\n" if avoid_repeats else "")
        + prompt
    )
    result = cleaner(await pool.generate(repair, before_request=pause_waiter))
    if not _cover_text_matches_topic(result, title, context, headline):
        raise ValueError("ИИ вернул фразу не по теме; перегенерируйте её или впишите свою")
    if avoid_repeats and headline and _cover_lines_repeat_meaningful_words(headline, result):
        raise ValueError("ИИ повторил слова главной строки; перегенерируйте подзаголовок")
    return result


async def _wait_for_cover_text_resume(kind: str) -> None:
    """Pause applies before each actual API call, including an automatic repair."""
    attribute = "cover_headlines_paused" if kind == "headline" else "cover_subheadlines_paused"
    while bool(getattr(load_settings(), attribute, False)):
        await asyncio.sleep(0.35)


def _save_cover_text_progress(settings: Settings) -> None:
    """Do not overwrite interactive cover-text controls during a running batch."""
    current = load_settings()
    settings.cover_text_use_structure = current.cover_text_use_structure
    settings.cover_text_avoid_repeats = current.cover_text_avoid_repeats
    settings.cover_headlines_paused = current.cover_headlines_paused
    settings.cover_subheadlines_paused = current.cover_subheadlines_paused
    _save_cover_state(settings)


def set_cover_text_pause(payload: dict, paused: bool) -> dict:
    settings = load_settings()
    _hydrate_cover_library(settings)
    kind = str(payload.get("kind", "")).strip().casefold()
    if kind not in {"headline", "subheadline"}:
        raise ValueError("Укажите, что поставить на паузу: заголовки или подзаголовки")
    attribute = "cover_headlines_paused" if kind == "headline" else "cover_subheadlines_paused"
    setattr(settings, attribute, paused)
    _save_cover_state(settings)
    label = "Заголовки" if kind == "headline" else "Подзаголовки"
    state = "поставлены на паузу после текущих запросов" if paused else "продолжены"
    return {**snapshot(), "operationResult": {"kind": f"cover-{kind}-pause", "count": 0,
                                                  "message": f"{label}: {state}."}}


def generate_cover_headlines(payload: dict) -> dict:
    settings = load_settings()
    _hydrate_cover_library(settings)
    if isinstance(payload.get("tabloidMode"), bool):
        settings.cover_tabloid_mode = bool(payload["tabloidMode"])
    provider = str(payload.get("provider", settings.cover_headline_provider)).strip().casefold()
    if provider not in {"agent", "openai"}:
        raise ValueError("Выберите «Агент NewsFlow» или «ChatGPT»")
    use_default = bool(payload.get("useDefault"))
    template = str(payload.get("template", "")).strip()
    if template and not use_default:
        settings.cover_headline_template = template[:12000]
    active_template = Settings().cover_headline_template if use_default else settings.cover_headline_template
    force = bool(payload.get("force") or payload.get("regenerate"))
    replace_manual = bool(payload.get("replaceManual"))
    scope = _current_cover_generation_scope(
        settings, payload, "Выберите сценарии для фраз на обложку",
    )
    selected = [(index, item) for index, item in scope
                if _cover_word_should_generate(item, "headline", force=force, replace_manual=replace_manual)]
    if not selected:
        return _cover_noop_result(
            "cover-headlines", "Все выбранные заголовки уже готовы; генерация не требуется.",
        )
    pool = HybridTextPool([], settings.openai_api_keys, "", settings.openai_model)
    settings.cover_headline_provider = provider
    for _index, item in selected:
        if str(item.get("title", "")).strip():
            item.update(headline_status="GENERATING", headline_error="")
    _save_cover_state(settings)

    async def build_one(index: int, item: dict):
        title = str(item.get("title", "")).strip()
        if not title:
            settings.cover_queue[index].update(headline_status="Ошибка заголовка", headline_error="У сценария нет названия")
            _save_cover_text_progress(settings)
            return
        provider_call = _BoundedCoverTextProvider(
            pool,
            lambda attempt: (
                item.update(headline_provider_attempt_count=attempt,
                            headline_status="RETRYING" if attempt > 1 else "GENERATING"),
                _save_cover_text_progress(settings),
            ),
        )
        try:
            variation = int(item.get("headline_variation_index", 0) or 0) + (1 if force else 0)
            structure = _cover_word_structure_pair(item, variation)
            recent = [row for row in settings.cover_queue if str(row.get("headline_status", "")).upper() == "READY"]
            headline, validation, attempts = await _generate_cover_word_v2(
                provider_call, "headline", item, active_template, structure,
                pause_waiter=lambda: _wait_for_cover_text_resume("headline"), recent=recent,
                tabloid_mode=settings.cover_tabloid_mode,
            )
            current = settings.cover_queue[index]
            current.update(cover_headline=headline, headline_source="AI", headline_status="READY", headline_error="",
                           headline_structure_id=structure["headline_structure_id"], headline_variation_index=variation,
                           headline_attempt_count=len(attempts), headline_semantic_slots=validation["semantic_slots"],
                           headline_repair_history=attempts, headline_pattern_signature=_cover_word_pattern_signature(headline),
                           text_style="TABLOID" if settings.cover_tabloid_mode else "STANDARD",
                           headline_candidate_count=int(validation.get("candidate_count", 1) or 1),
                           headline_selection_reason=str(validation.get("selection_reason", "validated candidate")),
                           headline_editorial_evaluation=dict(validation.get("editorial_evaluation", {})),
                           headline_selection_evidence=dict(validation.get("selection_evidence", {})),
                           headline_generation_timestamp=datetime.now().astimezone().isoformat(timespec="seconds"))
            _mark_cover_prompt_stale_for_current_text(current)
            current["headline_provider_attempt_count"] = provider_call.attempts
            current.pop("cover_headline_suggestion", None)
        except _BRIDGE_OPERATION_ERRORS as exc:
            settings.cover_queue[index].update(
                headline_status="FAILED", headline_error=_cover_provider_error_message(exc),
                headline_provider_attempt_count=provider_call.attempts,
            )
        # Each finished item is written immediately. Snapshot runs in a
        # separate bridge process every 900 ms, so the UI sees partial batch
        # progress rather than blank inputs until the slowest request finishes.
        _save_cover_text_progress(settings)

    async def build_all():
        return await asyncio.gather(*(build_one(index, item) for index, item in selected))

    asyncio.run(build_all())
    return snapshot()


def apply_cover_headline_suggestions(payload: dict) -> dict:
    """Move generated word suggestions into selected cover topics on demand."""
    settings = load_settings()
    _hydrate_cover_library(settings)
    requested = {int(index) for index in payload.get("indices", [])}
    if not requested:
        requested = set(range(len(settings.cover_queue)))
    applied = 0
    for index, item in enumerate(settings.cover_queue):
        if index not in requested:
            continue
        suggestion = _clean_cover_headline(str(item.get("cover_headline_suggestion", "")))
        if suggestion:
            item.update(cover_headline=suggestion, headline_status="Перенесено в тему")
            _mark_cover_prompt_stale_for_current_text(item)
            applied += 1
    if not applied:
        raise ValueError("Сначала создайте фразы ИИ для выбранных тем")
    _save_cover_state(settings)
    return {**snapshot(), "operationResult": {"kind": "cover-headlines", "count": applied,
                                                "message": f"Фразы перенесены в темы обложек: {applied}."}}


def generate_cover_subheadlines(payload: dict) -> dict:
    """Create a second thumbnail phrase without replacing the main headline."""
    settings = load_settings()
    _hydrate_cover_library(settings)
    if isinstance(payload.get("tabloidMode"), bool):
        settings.cover_tabloid_mode = bool(payload["tabloidMode"])
    provider = str(payload.get("provider", settings.cover_headline_provider)).strip().casefold()
    if provider not in {"agent", "openai"}:
        raise ValueError("Выберите «Агент NewsFlow» или «ChatGPT»")
    use_default = bool(payload.get("useDefault"))
    template = str(payload.get("template", "")).strip()
    if template and not use_default:
        settings.cover_subheadline_template = template[:12000]
    active_template = Settings().cover_subheadline_template if use_default else settings.cover_subheadline_template
    force = bool(payload.get("force") or payload.get("regenerate"))
    replace_manual = bool(payload.get("replaceManual"))
    scope = _current_cover_generation_scope(
        settings, payload, "Выберите сценарии для подзаголовков",
    )
    selected = [(index, item) for index, item in scope
                if _cover_word_should_generate(item, "subheadline", force=force, replace_manual=replace_manual)]
    if not selected:
        return _cover_noop_result(
            "cover-subheadlines", "Все выбранные подзаголовки уже готовы; генерация не требуется.",
        )
    pool = HybridTextPool([], settings.openai_api_keys, "", settings.openai_model)
    settings.cover_headline_provider = provider
    for _index, item in selected:
        if str(item.get("title", "")).strip():
            item.update(subheadline_status="GENERATING", subheadline_error="")
    _save_cover_state(settings)

    async def build_one(index: int, item: dict):
        title = str(item.get("title", "")).strip()
        if not title:
            settings.cover_queue[index].update(subheadline_status="Ошибка подзаголовка", subheadline_error="У сценария нет названия")
            _save_cover_text_progress(settings)
            return
        provider_call = _BoundedCoverTextProvider(
            pool,
            lambda attempt: (
                item.update(subheadline_provider_attempt_count=attempt,
                            subheadline_status="RETRYING" if attempt > 1 else "GENERATING"),
                _save_cover_text_progress(settings),
            ),
        )
        try:
            headline = str(item.get("cover_headline", "")).strip()
            if not headline:
                raise ValueError("Headline unavailable after retries; подзаголовок не создан")
            variation = int(item.get("headline_variation_index", 0) or 0)
            structure = _cover_word_structure_pair(item, variation)
            recent = [row for row in settings.cover_queue if str(row.get("subheadline_status", "")).upper() == "READY"]
            subheadline, validation, attempts = await _generate_cover_word_v2(
                provider_call, "subheadline", item, active_template, structure, headline=headline,
                pause_waiter=lambda: _wait_for_cover_text_resume("subheadline"), recent=recent,
                tabloid_mode=settings.cover_tabloid_mode,
            )
            current = settings.cover_queue[index]
            current.update(cover_subheadline=subheadline, subheadline_source="AI", subheadline_status="READY", subheadline_error="",
                           subheadline_structure_id=structure["subheadline_structure_id"],
                           subheadline_variation_index=variation, subheadline_attempt_count=len(attempts),
                           subheadline_semantic_slots=validation["semantic_slots"], subheadline_repair_history=attempts,
                           subheadline_pattern_signature=_cover_word_pattern_signature(subheadline),
                           text_style="TABLOID" if settings.cover_tabloid_mode else "STANDARD",
                           subheadline_candidate_count=int(validation.get("candidate_count", 1) or 1),
                           subheadline_selection_reason=str(validation.get("selection_reason", "validated candidate")),
                           subheadline_editorial_evaluation=dict(validation.get("editorial_evaluation", {})),
                           subheadline_selection_evidence=dict(validation.get("selection_evidence", {})),
                           subheadline_generation_timestamp=datetime.now().astimezone().isoformat(timespec="seconds"))
            _mark_cover_prompt_stale_for_current_text(current)
            current["subheadline_provider_attempt_count"] = provider_call.attempts
            current.pop("cover_subheadline_suggestion", None)
        except _BRIDGE_OPERATION_ERRORS as exc:
            settings.cover_queue[index].update(
                subheadline_status="FAILED", subheadline_error=_cover_provider_error_message(exc),
                subheadline_provider_attempt_count=provider_call.attempts,
            )
        _save_cover_text_progress(settings)

    async def build_all():
        return await asyncio.gather(*(build_one(index, item) for index, item in selected))

    asyncio.run(build_all())
    return snapshot()


