def cancel_cover_subheadlines(payload: dict) -> dict:
    """Clear only the secondary line; primary cover words always remain untouched."""
    settings = load_settings()
    _hydrate_cover_library(settings)
    requested = {int(index) for index in payload.get("indices", [])}
    if not requested:
        requested = set(range(len(settings.cover_queue)))
    removed = 0
    for index, item in enumerate(settings.cover_queue):
        if index not in requested:
            continue
        had_value = any(item.get(key) for key in ("cover_subheadline", "cover_subheadline_suggestion",
                                                   "subheadline_status", "subheadline_error"))
        for key in ("cover_subheadline", "cover_subheadline_suggestion", "subheadline_status", "subheadline_error"):
            item.pop(key, None)
        _mark_cover_prompt_stale_for_current_text(item)
        if had_value:
            removed += 1
    _save_cover_state(settings)
    scope = "выбранных тем" if payload.get("indices") else "всех тем"
    return {**snapshot(), "operationResult": {"kind": "cover-subheadlines-cancel", "count": removed,
                                                "message": f"Подзаголовки отменены для {scope}: {removed}. Основные слова сохранены."}}


_COVER_SUBHEADLINE_RECOVERY_FIELDS = (
    "cover_subheadline", "subheadline_source", "subheadline_status", "subheadline_error",
    "subheadline_structure_id", "subheadline_variation_index", "subheadline_attempt_count",
    "subheadline_semantic_slots", "subheadline_repair_history", "subheadline_pattern_signature",
    "subheadline_generation_timestamp",
)


def _restore_missing_cover_subheadlines(settings: Settings, interrupted_queue: list[dict]) -> int:
    """Restore completed secondary words from an interrupted atomic registry snapshot.

    It is deliberately additive: a line that has since been typed or generated
    is authoritative, and is never replaced by the old snapshot.
    """
    backup_by_identity = {
        str(item.get("production_item_id") or item.get("id") or item.get("title") or "").strip().casefold(): item
        for item in interrupted_queue
        if isinstance(item, dict) and str(item.get("cover_subheadline", "")).strip()
    }
    restored = 0
    for current in settings.cover_queue:
        identity = str(current.get("production_item_id") or current.get("id") or current.get("title") or "").strip().casefold()
        saved = backup_by_identity.get(identity)
        current_value = str(current.get("cover_subheadline", "")).strip()
        current_status = str(current.get("subheadline_status", "")).upper()
        if not saved or current_value or current_status in {"MANUAL", "READY"}:
            continue
        for field in _COVER_SUBHEADLINE_RECOVERY_FIELDS:
            if field in saved:
                current[field] = saved[field]
            else:
                current.pop(field, None)
        restored += 1
    return restored


def generate_cover_texts(payload: dict) -> dict:
    """Generate the two thumbnail text lines independently in one user action."""
    settings = load_settings()
    _hydrate_cover_library(settings)
    scope = _current_cover_generation_scope(
        settings, payload, "Выберите сценарии для текстов обложки",
    )
    durable_payload = dict(payload)
    durable_payload["indices"] = [index for index, _item in scope]
    durable_payload["productionItemIds"] = [
        str(item.get("production_item_id", "")).strip() for _index, item in scope
    ]
    headline_payload = dict(payload)
    headline_payload.update(durable_payload)
    headline_payload["template"] = str(payload.get("headlineTemplate", payload.get("template", "")))
    subheadline_payload = dict(payload)
    subheadline_payload.update(durable_payload)
    subheadline_payload["template"] = str(payload.get("subheadlineTemplate", ""))
    generate_cover_headlines(headline_payload)
    generate_cover_subheadlines(subheadline_payload)

    settings = load_settings()
    _hydrate_cover_library(settings)
    current = _select_current_cover_generation_rows(settings, durable_payload, lambda _item: True)
    headline_ready = sum(bool(str(item.get("cover_headline", "")).strip())
                         and str(item.get("headline_status", "")).upper() != "FAILED"
                         for _index, item in current)
    subheadline_ready = sum(bool(str(item.get("cover_subheadline", "")).strip())
                            and str(item.get("subheadline_status", "")).upper() != "FAILED"
                            for _index, item in current)
    failed = sum(any(str(item.get(key, "")).upper() == "FAILED"
                     for key in ("headline_status", "subheadline_status"))
                 for _index, item in current)
    ready = sum(bool(str(item.get("cover_headline", "")).strip())
                and bool(str(item.get("cover_subheadline", "")).strip())
                and not any(str(item.get(key, "")).upper() == "FAILED"
                            for key in ("headline_status", "subheadline_status"))
                for _index, item in current)
    requested = len(payload.get("indices", [])) or len(scope)
    return {
        **snapshot(),
        "operationResult": {
            "kind": "cover-texts", "count": ready, "requested": requested, "current": len(current),
            "headlineReady": headline_ready, "subheadlineReady": subheadline_ready, "failed": failed,
            "message": f"Тексты обложек: {ready}/{len(current)} готовы, ошибок: {failed}.",
        },
    }


def remove_cover_headline_suggestions(payload: dict) -> dict:
    """Remove only AI suggestions; never touch the user's applied cover words."""
    settings = load_settings()
    _hydrate_cover_library(settings)
    requested = {int(index) for index in payload.get("indices", [])}
    if not requested:
        requested = set(range(len(settings.cover_queue)))
    removed = 0
    for index, item in enumerate(settings.cover_queue):
        if index not in requested or not item.get("cover_headline_suggestion"):
            continue
        item.pop("cover_headline_suggestion", None)
        if str(item.get("headline_status", "")).startswith("Фраза предложена"):
            item["headline_status"] = ""
        removed += 1
    if not removed:
        raise ValueError("Нет предложений ИИ для удаления")
    _save_cover_state(settings)
    return {**snapshot(), "operationResult": {"kind": "cover-headlines-remove", "count": removed,
                                                "message": f"Предложения ИИ удалены: {removed}."}}


def import_cover_headlines(payload: dict) -> dict:
    """Apply user-loaded cover words line-by-line to selected (or all) topics."""
    settings = load_settings()
    _hydrate_cover_library(settings)
    phrases = [_clean_cover_headline(line) for line in str(payload.get("text", "")).replace("\r", "").split("\n")]
    phrases = [phrase for phrase in phrases if phrase]
    if not phrases:
        raise ValueError("В TXT не найдено слов для обложек: укажите одну фразу на строку")
    requested = [int(index) for index in payload.get("indices", [])]
    valid = [index for index in requested if 0 <= index < len(settings.cover_queue)]
    if not valid:
        valid = list(range(len(settings.cover_queue)))
    if not valid:
        raise ValueError("Сначала добавьте темы в очередь обложек")
    applied = 0
    for index, phrase in zip(valid, phrases):
        settings.cover_queue[index].update(cover_headline=phrase, headline_status="Загружено вручную")
        _mark_cover_prompt_stale_for_current_text(settings.cover_queue[index])
        applied += 1
    _save_cover_state(settings)
    return {**snapshot(), "operationResult": {"kind": "cover-own-headlines", "count": applied,
                                                "message": f"Ваши слова загружены в темы: {applied}."}}


_COVER_TEXT_IMPORT_LINE_LIMIT = 4_096


def _normalise_cover_text_import_title(value: object) -> str:
    """Technical-only identity key for an imported title, never a fuzzy match."""
    return " ".join(str(value or "").removeprefix("\ufeff").split())


def _parse_cover_text_triples(value: object) -> list[tuple[str, str, str]]:
    """Parse the documented title/headline/subheadline TXT triples exactly."""
    raw = str(value or "").removeprefix("\ufeff")
    lines = [line for line in raw.splitlines() if line.strip()]
    if not lines:
        raise ValueError("INVALID_TRIPLES: TXT не содержит непустых строк")
    if len(lines) % 3:
        raise ValueError("INVALID_TRIPLES: после удаления пустых строк число строк должно быть кратно 3")
    records: list[tuple[str, str, str]] = []
    seen: dict[str, tuple[str, str]] = {}
    for offset in range(0, len(lines), 3):
        title, headline, subheadline = lines[offset:offset + 3]
        normalized_title = _normalise_cover_text_import_title(title)
        if not normalized_title or not headline or not subheadline:
            raise ValueError("INVALID_TRIPLES: тема, headline и subheadline должны быть непустыми")
        if max(len(headline), len(subheadline)) > _COVER_TEXT_IMPORT_LINE_LIMIT:
            raise ValueError(f"TEXT_TOO_LONG: каждая строка headline/subheadline не больше {_COVER_TEXT_IMPORT_LINE_LIMIT} символов")
        prior = seen.get(normalized_title)
        current = (headline, subheadline)
        if prior is not None:
            if prior != current:
                raise ValueError(f"CONFLICTING_DUPLICATE: тема «{title}» встречается с разными текстами")
            continue
        seen[normalized_title] = current
        records.append((normalized_title, headline, subheadline))
    return records


def import_cover_text_triples(payload: dict) -> dict:
    """Atomically attach user-owned cover text to current rows by durable ID."""
    records = _parse_cover_text_triples(payload.get("text", ""))
    settings = load_settings()
    _hydrate_cover_library(settings)
    by_title: dict[str, list[str]] = {}
    by_production_item_id: dict[str, list[dict]] = {}
    for item in settings.cover_queue:
        if not isinstance(item, dict):
            continue
        normalized_title = _normalise_cover_text_import_title(item.get("title"))
        production_item_id = str(item.get("production_item_id") or item.get("productionItemId") or "").strip()
        if normalized_title:
            # Resolve identity first.  Nothing below relies on a queue index or
            # the row's original location, so sorting/filtering cannot redirect
            # a manual import to a neighbouring topic.
            by_title.setdefault(normalized_title, []).append(production_item_id)
        if production_item_id:
            by_production_item_id.setdefault(production_item_id, []).append(item)

    resolved: list[tuple[str, str, str]] = []
    for normalized_title, headline, subheadline in records:
        candidates = by_title.get(normalized_title, [])
        if not candidates:
            raise ValueError(f"UNKNOWN_TOPIC: тема «{normalized_title}» отсутствует в текущей очереди обложек")
        if len(candidates) != 1:
            raise ValueError(f"AMBIGUOUS_TOPIC: тема «{normalized_title}» соответствует нескольким строкам обложек")
        production_item_id = candidates[0]
        if not production_item_id:
            raise ValueError(f"MISSING_PRODUCTION_ITEM_ID: у темы «{normalized_title}» нет durable ProductionItem ID")
        item_candidates = by_production_item_id.get(production_item_id, [])
        if not item_candidates:
            raise ValueError(f"MISSING_PRODUCTION_ITEM_ID: ProductionItem ID «{production_item_id}» отсутствует в текущей очереди")
        if len(item_candidates) != 1:
            raise ValueError(f"AMBIGUOUS_PRODUCTION_ITEM_ID: ProductionItem ID «{production_item_id}» встречается в нескольких строках")
        resolved.append((production_item_id, headline, subheadline))

    # All validation above completes before the first mutation or persistence.
    for production_item_id, headline, subheadline in resolved:
        item = by_production_item_id[production_item_id][0]
        item.update(
            cover_headline=headline,
            headline_source="MANUAL",
            headline_status="MANUAL",
            headline_error="",
            cover_subheadline=subheadline,
            subheadline_source="MANUAL",
            subheadline_status="MANUAL",
            subheadline_error="",
        )
        _mark_cover_prompt_stale_for_current_text(item)
    _save_cover_state(settings)
    return {**snapshot(), "operationResult": {
        "kind": "cover-text-triples-import",
        "count": len(resolved),
        "message": f"Ручные headline и subheadline импортированы: {len(resolved)}.",
        "productionItemIds": [production_item_id for production_item_id, _headline, _subheadline in resolved],
    }}


def _parse_cover_prompt_pairs(value: object) -> list[tuple[str, str]]:
    """Parse strict title/manual-prompt pairs without guessing their identity."""
    raw = str(value or "").removeprefix("\ufeff")
    lines = [line for line in raw.splitlines() if line.strip()]
    if not lines:
        raise ValueError("INVALID_PAIRS: TXT не содержит непустых строк")
    if len(lines) % 2:
        raise ValueError("INVALID_PAIRS: после удаления пустых строк число строк должно быть кратно 2")
    records: list[tuple[str, str]] = []
    seen: dict[str, str] = {}
    for offset in range(0, len(lines), 2):
        title, prompt = lines[offset:offset + 2]
        normalized_title = _normalise_cover_text_import_title(title)
        if not normalized_title or not prompt.strip():
            raise ValueError("INVALID_PAIRS: тема и ручной промпт должны быть непустыми")
        prior = seen.get(normalized_title)
        if prior is not None:
            if prior != prompt:
                raise ValueError(f"CONFLICTING_DUPLICATE: тема «{title}» встречается с разными промптами")
            continue
        seen[normalized_title] = prompt
        records.append((normalized_title, prompt))
    return records


def _cover_rows_by_title_and_production_id(settings: Settings) -> tuple[dict[str, list[str]], dict[str, list[dict]]]:
    """Build identity maps without retaining a queue-order contract."""
    by_title: dict[str, list[str]] = {}
    by_production_item_id: dict[str, list[dict]] = {}
    for item in settings.cover_queue:
        if not isinstance(item, dict):
            continue
        title = _normalise_cover_text_import_title(item.get("title"))
        production_item_id = str(item.get("production_item_id") or item.get("productionItemId") or "").strip()
        if title:
            by_title.setdefault(title, []).append(production_item_id)
        if production_item_id:
            by_production_item_id.setdefault(production_item_id, []).append(item)
    return by_title, by_production_item_id


def _resolve_cover_prompt_import_ids(settings: Settings, records: list[tuple[str, str]]) -> list[tuple[str, str]]:
    """Resolve every imported title before a prompt row is allowed to mutate."""
    by_title, by_production_item_id = _cover_rows_by_title_and_production_id(settings)
    resolved: list[tuple[str, str]] = []
    for normalized_title, prompt in records:
        candidates = by_title.get(normalized_title, [])
        if not candidates:
            raise ValueError(f"UNKNOWN_TOPIC: тема «{normalized_title}» отсутствует в текущей очереди обложек")
        if len(candidates) != 1:
            raise ValueError(f"AMBIGUOUS_TOPIC: тема «{normalized_title}» соответствует нескольким строкам обложек")
        production_item_id = candidates[0]
        if not production_item_id:
            raise ValueError(f"MISSING_PRODUCTION_ITEM_ID: у темы «{normalized_title}» нет durable ProductionItem ID")
        if len(by_production_item_id.get(production_item_id, [])) != 1:
            raise ValueError(f"AMBIGUOUS_PRODUCTION_ITEM_ID: ProductionItem ID «{production_item_id}» встречается в нескольких строках")
        resolved.append((production_item_id, prompt))
    return resolved


def _replace_manual_cover_prompt(item: dict, prompt: str) -> None:
    """Replace one visual brief without invoking a provider or changing topic-owned inputs."""
    old_options = [
        value for value in _cover_active_prompt_options(item)
        if _cover_prompt_key(value) != _cover_prompt_key(prompt)
    ]
    item.update(
        image_prompt=prompt,
        image_prompt_options=[prompt],
        selected_prompt_index=0,
        prompt_provider="manual",
        prompt_text_signature=_cover_text_revision(item),
        prompt_revision_id=_cover_prompt_revision({**item, "image_prompt": prompt}),
    )
    _remember_cover_prompt_history(item, old_options)
    _clear_obsolete_fresh_prompt_contract(item)
    _clear_cover_render_state(item, status="Промпт сохранён вручную")
    item.update(status="Промпт сохранён вручную", progress=0, error="")
    _cover_step(item, "Промпт сохранён вручную", 0, "Ручной промпт готов к обычному запуску Covers")


def import_cover_prompt_pairs(payload: dict) -> dict:
    """Atomically import user-owned visual prompts by exact title then durable ID."""
    records = _parse_cover_prompt_pairs(payload.get("text", ""))
    settings = load_settings()
    _hydrate_cover_library(settings)
    resolved = _resolve_cover_prompt_import_ids(settings, records)
    _by_title, by_production_item_id = _cover_rows_by_title_and_production_id(settings)

    # All parsing, title matching and durable-ID validation happens before a
    # single row changes, so a bad pair can never partially import the file.
    for production_item_id, prompt in resolved:
        _replace_manual_cover_prompt(by_production_item_id[production_item_id][0], prompt)
    _save_cover_state(settings)
    return {**snapshot(), "operationResult": {
        "kind": "cover-prompt-pairs-import",
        "count": len(resolved),
        "message": f"Ручные промпты импортированы: {len(resolved)}.",
        "productionItemIds": [production_item_id for production_item_id, _prompt in resolved],
    }}


def save_cover_manual_prompt(payload: dict) -> dict:
    """Save a typed visual prompt to exactly one durable ProductionItem."""
    production_item_id = str(payload.get("productionItemId") or "").strip()
    prompt = str(payload.get("prompt", ""))
    if not production_item_id:
        raise ValueError("MISSING_PRODUCTION_ITEM_ID: выберите тему с durable ProductionItem ID")
    if not prompt.strip():
        raise ValueError("MANUAL_PROMPT_EMPTY: заполните ручной промпт")
    settings = load_settings()
    _hydrate_cover_library(settings)
    _by_title, by_production_item_id = _cover_rows_by_title_and_production_id(settings)
    matches = by_production_item_id.get(production_item_id, [])
    if len(matches) != 1:
        raise ValueError(f"AMBIGUOUS_PRODUCTION_ITEM_ID: ProductionItem ID «{production_item_id}» не разрешён однозначно")
    _replace_manual_cover_prompt(matches[0], prompt)
    _save_cover_state(settings)
    return {**snapshot(), "operationResult": {
        "kind": "cover-manual-prompt-save",
        "count": 1,
        "message": "Ручной промпт сохранён.",
        "productionItemIds": [production_item_id],
    }}


def remove_cover_headlines(payload: dict) -> dict:
    """Clear rendered headlines, regardless of whether AI or the user wrote them."""
    settings = load_settings()
    _hydrate_cover_library(settings)
    requested = {int(index) for index in payload.get("indices", [])}
    if not requested:
        requested = set(range(len(settings.cover_queue)))
    removed = 0
    for index, item in enumerate(settings.cover_queue):
        if index not in requested or not item.get("cover_headline"):
            continue
        item.pop("cover_headline", None)
        item.pop("cover_headline_suggestion", None)
        item["headline_status"] = ""
        item["headline_error"] = ""
        _mark_cover_prompt_stale_for_current_text(item)
        removed += 1
    if not removed:
        raise ValueError("Нет ваших слов на обложке для удаления")
    _save_cover_state(settings)
    scope = "выбранных тем" if payload.get("indices") else "всех тем"
    return {**snapshot(), "operationResult": {"kind": "cover-headlines-remove", "count": removed,
                                                "message": f"Заголовки удалены для {scope}: {removed}."}}


def import_cover_topics(payload: dict) -> dict:
    """Add one cover topic per non-empty line from a user TXT/MD file."""
    raw = str(payload.get("text", ""))
    titles = []
    for line in raw.replace("\r", "").split("\n"):
        title = re.sub(r"^\s*(?:[-*•]|\d+[.)])\s*", "", line).strip()
        if title and title.casefold() not in {value.casefold() for value in titles}:
            titles.append(title[:300])
    if not titles:
        raise ValueError("В TXT не найдено тем: укажите одну тему в каждой непустой строке или абзаце")
    settings = load_settings()
    _hydrate_cover_library(settings)
    existing = {str(item.get("title", "")).casefold() for item in settings.cover_queue}
    added = 0
    for title in titles:
        if title.casefold() in existing:
            continue
        settings.cover_queue.append({"title": title, "script": "", "scenario_index": len(settings.cover_queue) + 1,
                                     "status": "Ожидает", "path": "", "error": "", "headline_status": ""})
        existing.add(title.casefold())
        added += 1
    _save_cover_state(settings)
    return {**snapshot(), "operationResult": {"kind": "cover-topics-import", "count": added,
                                                "message": f"Тем добавлено в обложки: {added}."}}


def save_cover_headline(payload: dict) -> dict:
    settings = load_settings()
    _hydrate_cover_library(settings)
    index = int(payload.get("index", -1))
    if not 0 <= index < len(settings.cover_queue):
        raise ValueError("Сценарий обложки не найден")
    text = " ".join(str(payload.get("headline", "")).split())
    settings.cover_queue[index].update(cover_headline=text, headline_source="MANUAL",
                                       headline_status="MANUAL" if text else "", headline_error="")
    _mark_cover_prompt_stale_for_current_text(settings.cover_queue[index])
    _save_cover_state(settings)
    return snapshot()


def save_cover_subheadline(payload: dict) -> dict:
    """Save the secondary thumbnail line typed directly in the cover row."""
    settings = load_settings()
    _hydrate_cover_library(settings)
    index = int(payload.get("index", -1))
    if not 0 <= index < len(settings.cover_queue):
        raise ValueError("Сценарий обложки не найден")
    text = _clean_cover_subheadline(str(payload.get("subheadline", "")))
    headline = _clean_cover_headline(str(settings.cover_queue[index].get("cover_headline", "")))
    if settings.cover_text_avoid_repeats and headline and text and _cover_lines_repeat_meaningful_words(headline, text):
        raise ValueError("Подзаголовок повторяет значимые слова из заголовка. Выключите «Без повторов», если это нужно намеренно.")
    settings.cover_queue[index].update(
        cover_subheadline=text,
        subheadline_source="MANUAL",
        subheadline_status="MANUAL" if text else "",
        subheadline_error="",
    )
    _mark_cover_prompt_stale_for_current_text(settings.cover_queue[index])
    _save_cover_state(settings)
    return snapshot()


def export_cover_prompts(payload: dict) -> dict:
    settings = load_settings()
    path = Path(str(payload.get("path", "")).strip())
    if not str(path):
        raise ValueError("Выберите место для TXT с промптами")
    requested = {int(index) for index in payload.get("indices", [])}
    rows = [(index, item) for index, item in enumerate(settings.cover_queue)
            if not requested or index in requested]
    if not rows:
        raise ValueError("Нет промптов для выгрузки")
    content = []
    for number, (_index, item) in enumerate(rows, 1):
        options = item.get("image_prompt_options") or [item.get("image_prompt") or "Промпт ещё не создан"]
        variants = "\n".join(f"  Вариант {variant + 1}{' (выбран)' if variant == int(item.get('selected_prompt_index', 0)) else ''}:\n  {prompt}"
                             for variant, prompt in enumerate(options))
        headline = str(item.get("cover_headline") or "")
        subheadline = str(item.get("cover_subheadline") or "")
        content.append(f"{number}. {item.get('title', '')}\nТекст на обложке: {headline or 'не задан'}\nПодзаголовок: {subheadline or 'не задан'}\n{variants}")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n\n".join(content) + "\n", encoding="utf-8-sig")
    return {**snapshot(), "operationResult": {"kind": "cover-prompts", "count": len(rows), "folder": str(path.parent),
                                                 "message": f"Промпты обложек сохранены: {path.name}"}}


def save_cover_prompt_preset(payload: dict) -> dict:
    settings = load_settings()
    name = " ".join(str(payload.get("name", "")).split())
    template = str(payload.get("promptTemplate", "")).strip()
    if not name:
        raise ValueError("Укажите название пресета обложек")
    if not template:
        raise ValueError("Заполните основной промпт перед сохранением")
    preset = {
        "name": name,
        "provider": str(payload.get("provider", settings.cover_prompt_provider)).casefold(),
        "promptTemplate": template,
        "ranges": _clean_cover_ranges(payload.get("ranges", [])),
        "useScriptContext": bool(payload.get("useScriptContext", settings.cover_use_script_context)),
        "headlineProvider": str(payload.get("headlineProvider", settings.cover_headline_provider)).casefold(),
        "headlineTemplate": str(payload.get("headlineTemplate", settings.cover_headline_template)).strip(),
        "subheadlineTemplate": str(payload.get("subheadlineTemplate", settings.cover_subheadline_template)).strip(),
        "textMode": str(payload.get("textMode", settings.cover_text_mode)),
    }
    settings.cover_prompt_presets = [item for item in settings.cover_prompt_presets
                                     if str(item.get("name", "")).casefold() != name.casefold()]
    settings.cover_prompt_presets.append(preset)
    save_settings(settings)
    return {**snapshot(), "operationResult": {"kind": "cover-preset", "count": 1,
                                                 "message": f"Пресет обложек «{name}» сохранён."}}


def delete_cover_prompt_preset(payload: dict) -> dict:
    settings = load_settings()
    name = " ".join(str(payload.get("name", "")).split())
    before = len(settings.cover_prompt_presets)
    settings.cover_prompt_presets = [item for item in settings.cover_prompt_presets
                                     if str(item.get("name", "")).casefold() != name.casefold()]
    if len(settings.cover_prompt_presets) == before:
        raise ValueError("Пресет обложек не найден")
    save_settings(settings)
    return snapshot()


