def upload_publication_v2_snapshots(payload: dict) -> dict:
    """Upload selected frozen snapshots with durable leases and resumable sessions."""
    requested = list(dict.fromkeys(
        str(value).strip() for value in payload.get("snapshotIds", []) if str(value).strip()
    ))
    if not requested:
        raise ValueError("Выберите хотя бы один подтверждённый snapshot для загрузки.")
    settings = load_settings()
    if settings.youtube_publication_queue_paused:
        raise ValueError("Очередь публикаций приостановлена.")
    executions = dict(settings.youtube_publication_executions or {})
    snapshots = dict(settings.youtube_publication_snapshots or {})
    missing = [
        snapshot_id for snapshot_id in requested
        if snapshot_id not in executions or snapshot_id not in snapshots
    ]
    if missing:
        raise ValueError("Один или несколько подтверждённых snapshots не найдены.")

    limit = max(1, int(settings.youtube_publication_upload_concurrency or 1))
    active = sum(
        1 for execution in executions.values()
        if str((execution.get("steps", {}).get("VIDEO_UPLOAD", {}) or {}).get("status", "")).upper() == "RUNNING"
    )
    available = max(0, limit - active)
    worker_prefix = f"publication-v2-{uuid.uuid4().hex[:8]}"
    blocked: list[tuple[str, str]] = []
    if not available:
        return {**snapshot(), "operationResult": {
            "kind": "publication-v2-upload",
            "count": 0,
            "failed": 0,
            "message": "Все upload workers заняты; новые передачи останутся в очереди.",
        }}

    lock = threading.Lock()
    succeeded: list[str] = []
    failures: list[tuple[str, str]] = []

    def upload_one(position: int, snapshot_id: str) -> None:
        worker_id = f"{worker_prefix}-{position + 1}"
        with lock:
            preflight = validate_publication_snapshot(settings, snapshot_id)
            execution_before = dict((settings.youtube_publication_executions or {}).get(snapshot_id, {}) or {})
            reupload_before = dict(execution_before.get("reupload", {}) or {})
            resume_state = dict(execution_before.get("resumableUpload", {}) or {})
            if str(resume_state.get("status", "")).upper() == "EXPIRED":
                blocked.append((
                    snapshot_id,
                    "Resumable session истёк. Сначала сверьте YouTube и явно разрешите новую загрузку.",
                ))
                return
            if preflight["uploadAlreadyExists"]:
                blocked.append((snapshot_id, "MP4 уже имеет YouTube ID; повторная загрузка запрещена"))
                return
            if not preflight["ok"]:
                first = preflight["reasons"][0]
                failed_stage = "AUTH_CHECK" if str(first["kind"]).upper() == "AUTH_REQUIRED" else "VIDEO_UPLOAD"
                fail_publication_stage(
                    settings, snapshot_id, failed_stage,
                    str(first["kind"]), str(first["message"]),
                )
                save_settings(settings)
                blocked.append((snapshot_id, str(first["message"])))
                return
            snapshot_record = dict(snapshots[snapshot_id])
            metadata = dict(snapshot_record.get("metadata", {}) or {})
            channel_id = str(snapshot_record.get("channelId", "")).strip()
            credentials = json.loads(settings.youtube_oauth_tokens[channel_id])

        try:
            profile, validated_credentials = fetch_current_channel(credentials)
        except _BRIDGE_OPERATION_ERRORS as exc:
            with lock:
                fail_publication_stage(
                    settings, snapshot_id, "AUTH_CHECK",
                    classify_publication_error(exc), str(exc),
                )
                save_settings(settings)
                blocked.append((snapshot_id, str(exc)))
            return

        configured_channel = next((
            dict(channel or {}) for channel in settings.analytics_channels
            if str(dict(channel or {}).get("profile_id", "")).strip() == channel_id
        ), {})
        expected_youtube_channel_id = str(configured_channel.get("channel_id", "")).strip()
        actual_youtube_channel_id = str(dict(profile or {}).get("channelId", "")).strip()
        if expected_youtube_channel_id and actual_youtube_channel_id != expected_youtube_channel_id:
            message = "OAuth подключён к другому YouTube-каналу. Переподключите выбранный канал."
            with lock:
                fail_publication_stage(settings, snapshot_id, "AUTH_CHECK", "AUTH_REQUIRED", message)
                save_settings(settings)
                blocked.append((snapshot_id, message))
            return

        with lock:
            settings.youtube_oauth_tokens[channel_id] = json.dumps(validated_credentials, ensure_ascii=False)
            try:
                begin_upload_attempt(settings, snapshot_id, worker_id)
                save_settings(settings)
            except _BRIDGE_OPERATION_ERRORS as exc:
                blocked.append((snapshot_id, str(exc)))
                return

        # A replacement always starts private and unscheduled.  The frozen
        # title/description/tags were explicitly reconfirmed by the operator,
        # but the old publication time is audit-only until separately reviewed.
        is_reupload = bool(reupload_before)
        body = build_private_video_insert_body(
            title=resolve_publication_upload_title(metadata),
            description=str(metadata.get("description", "")),
            tags=[str(value) for value in metadata.get("tags", []) if str(value).strip()],
            hashtags=[str(value) for value in metadata.get("hashtags", []) if str(value).strip()],
            publish_at="" if is_reupload else str(snapshot_record.get("requestedPublishAt", "") or ""),
            privacy="private" if is_reupload else str(snapshot_record.get("privacy", "private")),
        )

        transport_started = bool(str(resume_state.get("sessionUri", "")).strip())

        def mark_transport_started() -> None:
            nonlocal transport_started
            transport_started = True

        def record_session_state(state: dict) -> None:
            with lock:
                execution = dict(settings.youtube_publication_executions.get(snapshot_id, {}) or {})
                execution["resumableUpload"] = {
                    "sessionUri": str(state.get("sessionUri", "")),
                    "bytesSent": max(0, int(state.get("bytesSent", 0) or 0)),
                    "totalBytes": max(0, int(state.get("totalBytes", 0) or 0)),
                    "status": "ACTIVE",
                    "updatedAt": datetime.now().astimezone().isoformat(),
                }
                settings.youtube_publication_executions[snapshot_id] = execution
                save_settings(settings)

        def record_upload_progress(progress: dict) -> None:
            with lock:
                execution = dict(settings.youtube_publication_executions.get(snapshot_id, {}) or {})
                steps = dict(execution.get("steps", {}) or {})
                step = dict(steps.get("VIDEO_UPLOAD", {}) or {})
                step["progress"] = {
                    "state": "transferring",
                    "bytesSent": max(0, int(progress.get("bytesSent", 0) or 0)),
                    "totalBytes": max(0, int(progress.get("totalBytes", 0) or 0)),
                    "percent": max(0, min(100, int(progress.get("percent", 0) or 0))),
                }
                steps["VIDEO_UPLOAD"] = step
                execution["steps"] = steps
                reupload = dict(execution.get("reupload", {}) or {})
                if reupload:
                    reupload["lastCheckedAt"] = datetime.now().astimezone().isoformat()
                    execution["reupload"] = reupload
                settings.youtube_publication_executions[snapshot_id] = execution
                save_settings(settings)

        try:
            result, refreshed = upload_private_video(
                validated_credentials,
                video_path=str(snapshot_record.get("videoPath", "")),
                body=body,
                thumbnail_path="",
                on_insert_started=mark_transport_started,
                on_progress=record_upload_progress,
                on_session_state=record_session_state,
                resume_state=resume_state,
            )
            with lock:
                complete_upload_attempt(settings, snapshot_id, worker_id, result)
                settings.youtube_oauth_tokens[channel_id] = json.dumps(refreshed, ensure_ascii=False)
                save_settings(settings)
                succeeded.append(snapshot_id)
        except _BRIDGE_OPERATION_ERRORS as exc:
            with lock:
                execution = dict(settings.youtube_publication_executions.get(snapshot_id, {}) or {})
                persisted_resume = dict(execution.get("resumableUpload", {}) or {})
                resume_saved = bool(str(persisted_resume.get("sessionUri", "")).strip())
                if isinstance(exc, ResumableUploadSessionExpired):
                    category = "USER_ACTION_REQUIRED"
                    message = str(exc)
                    persisted_resume.update({
                        "status": "EXPIRED",
                        "expiredAt": datetime.now().astimezone().isoformat(),
                    })
                    execution["resumableUpload"] = persisted_resume
                    settings.youtube_publication_executions[snapshot_id] = execution
                elif resume_saved:
                    category = "RETRYABLE"
                    message = (
                        "Передача прервана; resumable session сохранена. "
                        "«Попробовать ещё раз» продолжит тот же upload без нового videos.insert."
                    )
                elif transport_started:
                    category = "USER_ACTION_REQUIRED"
                    message = (
                        "Исход создания upload session неизвестен. "
                        "Сверьте канал перед новой отправкой MP4."
                    )
                else:
                    category = classify_publication_error(exc)
                    message = str(exc)
                fail_publication_stage(settings, snapshot_id, "VIDEO_UPLOAD", category, message)
                release_execution(settings, snapshot_id, worker_id)
                save_settings(settings)
                failures.append((snapshot_id, message))

    with ThreadPoolExecutor(
        max_workers=min(available, len(requested)),
        thread_name_prefix="newsflow-publication-v2",
    ) as executor:
        futures = [
            executor.submit(upload_one, position, snapshot_id)
            for position, snapshot_id in enumerate(requested)
        ]
        for future in as_completed(futures):
            future.result()

    return {**snapshot(), "operationResult": {
        "kind": "publication-v2-upload",
        "count": len(succeeded),
        "failed": len(failures) + len(blocked),
        "message": (
            f"Передано MP4: {len(succeeded)}. "
            f"Ошибок или блокировок: {len(failures) + len(blocked)}."
        ),
    }}


def reconcile_publication_v2_youtube(payload: dict) -> dict:
    """Read back known YouTube IDs; statusOnly never queues Studio work."""
    requested = list(dict.fromkeys(
        str(value).strip() for value in payload.get("snapshotIds", []) if str(value).strip()
    ))
    if not requested:
        raise ValueError("Выберите хотя бы один snapshot для проверки YouTube.")
    status_only = bool(payload.get("statusOnly", False))
    settings = load_settings()
    confirmed = 0
    failures: list[tuple[str, str]] = []
    for snapshot_id in requested:
        snapshot_record = dict((settings.youtube_publication_snapshots or {}).get(snapshot_id, {}) or {})
        execution = dict((settings.youtube_publication_executions or {}).get(snapshot_id, {}) or {})
        video_id = str(execution.get("youtubeVideoId") or "").strip()
        channel_id = str(snapshot_record.get("channelId", "")).strip()
        if not snapshot_record or not video_id:
            failures.append((snapshot_id, "Для проверки требуется сохранённый YouTube ID."))
            continue
        try:
            credentials = json.loads(settings.youtube_oauth_tokens[channel_id])
            video, refreshed = fetch_youtube_video_state(credentials, video_id)
            reconcile_youtube_video_state(settings, snapshot_id, video)
            settings.youtube_oauth_tokens[channel_id] = json.dumps(refreshed, ensure_ascii=False)
            if not status_only:
                _queue_publication_v2_engagement_task(settings, snapshot_id)
            confirmed += 1
        except _BRIDGE_OPERATION_ERRORS as exc:
            fail_publication_stage(
                settings, snapshot_id, "YOUTUBE_PROCESSING",
                classify_publication_error(exc), str(exc),
            )
            failures.append((snapshot_id, str(exc)))
    save_settings(settings)
    return {**snapshot(), "operationResult": {
        "kind": "publication-v2-status-refresh" if status_only else "publication-v2-reconcile",
        "count": confirmed,
        "failed": len(failures),
        "message": (
            f"Статусы YouTube обновлены: {confirmed}. Ошибок: {len(failures)}."
            if status_only
            else f"YouTube подтверждён для роликов: {confirmed}. Ошибок: {len(failures)}."
        ),
    }}


def run_publication_v2_thumbnails(payload: dict) -> dict:
    """Apply only the thumbnail stage to known videos; MP4 transport is never invoked here."""
    requested = list(dict.fromkeys(str(value).strip() for value in payload.get("snapshotIds", []) if str(value).strip()))
    if not requested:
        raise ValueError("Выберите хотя бы один snapshot для установки обложки.")
    settings = load_settings()
    succeeded = 0
    failures: list[tuple[str, str]] = []
    for position, snapshot_id in enumerate(requested, start=1):
        snapshot_record = dict((settings.youtube_publication_snapshots or {}).get(snapshot_id, {}) or {})
        execution = dict((settings.youtube_publication_executions or {}).get(snapshot_id, {}) or {})
        thumbnail_state = str(dict(dict(execution.get("steps", {}) or {}).get("THUMBNAIL", {}) or {}).get("status", "")).upper()
        if thumbnail_state in {"SUCCESS", "SKIPPED", "NOT_REQUIRED"}:
            continue
        video_id = str(execution.get("youtubeVideoId") or "").strip()
        channel_id = str(snapshot_record.get("channelId", "")).strip()
        thumbnail_path = str(snapshot_record.get("thumbnailPath", "")).strip()
        if not snapshot_record or not video_id:
            failures.append((snapshot_id, "Нельзя поставить обложку до подтверждённого YouTube ID."))
            continue
        if not thumbnail_path or not Path(thumbnail_path).is_file():
            fail_publication_stage(settings, snapshot_id, "THUMBNAIL", "USER_ACTION_REQUIRED", "Файл обложки не найден; загрузка MP4 сохранена.")
            failures.append((snapshot_id, "Файл обложки не найден."))
            continue
        if not frozen_artifact_matches(snapshot_record, "thumbnail", thumbnail_path):
            fail_publication_stage(
                settings, snapshot_id, "THUMBNAIL", "USER_ACTION_REQUIRED",
                "Файл обложки изменился после подтверждения snapshot; загрузка MP4 сохранена.",
            )
            failures.append((snapshot_id, "Файл обложки изменился после подтверждения snapshot."))
            continue
        worker_id = f"publication-v2-thumbnail-{uuid.uuid4().hex[:8]}-{position}"
        if not claim_execution(settings, snapshot_id, worker_id):
            failures.append((snapshot_id, "Snapshot занят другим worker."))
            continue
        steps = dict(settings.youtube_publication_executions[snapshot_id].get("steps", {}) or {})
        step = dict(steps.get("THUMBNAIL", {}) or {})
        step.update({"status": "RUNNING", "attempts": int(step.get("attempts", 0) or 0) + 1, "startedAt": datetime.now().astimezone().isoformat(), "error": None})
        steps["THUMBNAIL"] = step
        settings.youtube_publication_executions[snapshot_id]["steps"] = steps
        settings.youtube_publication_executions[snapshot_id]["currentStage"] = "THUMBNAIL"
        save_settings(settings)
        try:
            credentials = json.loads(settings.youtube_oauth_tokens[channel_id])
            result = set_youtube_thumbnail(credentials, video_id, thumbnail_path)
            complete_publication_stage(settings, snapshot_id, worker_id, "THUMBNAIL", {"path": thumbnail_path, "response": result.get("response", {})})
            settings.youtube_oauth_tokens[channel_id] = json.dumps(result.get("credentials", credentials), ensure_ascii=False)
            save_settings(settings)
            succeeded += 1
        except _BRIDGE_OPERATION_ERRORS as exc:
            fail_publication_stage(settings, snapshot_id, "THUMBNAIL", classify_publication_error(exc), str(exc))
            release_execution(settings, snapshot_id, worker_id)
            save_settings(settings)
            failures.append((snapshot_id, str(exc)))
    return {**snapshot(), "operationResult": {"kind": "publication-v2-thumbnail", "count": succeeded,
            "failed": len(failures), "message": f"Обложки установлены: {succeeded}. Ошибок: {len(failures)}."}}




def run_publication_v2_studio(payload: dict) -> dict:
    """Continue selected V2 snapshots through confirmed Studio-only stages.

    Every action is leased and persisted independently, so a failed card/end
    screen/ads/post attempt never reopens VIDEO_UPLOAD or another completed
    irreversible stage.
    """

    requested = list(dict.fromkeys(
        str(value).strip() for value in payload.get("snapshotIds", []) if str(value).strip()
    ))
    if not requested:
        raise ValueError("Выберите хотя бы один snapshot для оформления в Studio.")
    requested_kinds = {
        str(value).strip().casefold()
        for value in payload.get("steps", [])
        if str(value).strip()
    }
    allowed_kinds = {"ads", "post", "cards", "end-screen"}
    if requested_kinds - allowed_kinds:
        raise ValueError("Выбраны неизвестные этапы Studio V2.")
    if not requested_kinds:
        requested_kinds = set(allowed_kinds)

    settings = load_settings()
    channels = {
        str(item.get("profile_id", "")).strip(): dict(item)
        for item in settings.analytics_channels
        if isinstance(item, dict)
    }
    snapshots = dict(settings.youtube_publication_snapshots or {})
    executions = dict(settings.youtube_publication_executions or {})

    catalog = [
        {
            "videoId": str(item.get("videoId", "")).strip(),
            "channelId": str(item.get("channelId", "")).strip(),
            "title": str(item.get("seoTitle") or item.get("title", "")).strip(),
            "privacyStatus": str(item.get("youtubePrivacyStatus", "")).strip(),
            "publishedAt": str(item.get("publishAt", "")).strip(),
            "score": item.get("engagementScore", 0),
        }
        for item in settings.youtube_publication_jobs
        if isinstance(item, dict) and str(item.get("videoId", "")).strip()
    ]
    for known_snapshot_id, known_snapshot in snapshots.items():
        known_execution = dict(executions.get(known_snapshot_id, {}) or {})
        known_video_id = str(known_execution.get("youtubeVideoId") or "").strip()
        if not known_video_id:
            continue
        known_metadata = dict(dict(known_snapshot or {}).get("metadata", {}) or {})
        catalog.append({
            "videoId": known_video_id,
            "channelId": str(dict(known_snapshot or {}).get("channelId", "")).strip(),
            "title": str(known_metadata.get("title", "")).strip(),
            "privacyStatus": str(known_execution.get("youtubePrivacyStatus") or "").strip(),
            "publishedAt": str(known_execution.get("actualPublishedAt") or known_execution.get("confirmedPublishAt") or "").strip(),
            "score": 0,
        })

    succeeded = failed = skipped = 0
    stage_map = {"ads": "ADS", "post": "POST", "cards": "CARDS", "end-screen": "END_SCREEN"}
    terminal = {"SUCCESS", "SKIPPED", "NOT_REQUIRED"}

    for snapshot_id in requested:
        snapshot_record = dict(snapshots.get(snapshot_id, {}) or {})
        execution = dict(executions.get(snapshot_id, {}) or {})
        if not snapshot_record or not execution:
            failed += 1
            continue
        video_id = str(execution.get("youtubeVideoId") or "").strip()
        if not video_id:
            fail_publication_stage(
                settings, snapshot_id, "ADS", "USER_ACTION_REQUIRED",
                "Studio-оформление нельзя запускать до подтверждённого YouTube video ID.",
            )
            failed += 1
            continue

        channel_id = str(snapshot_record.get("channelId", "")).strip()
        channel = channels.get(channel_id)
        if not channel or not str(channel.get("channel_id", "")).strip():
            fail_publication_stage(
                settings, snapshot_id, "ADS", "USER_ACTION_REQUIRED",
                "Для Studio-оформления не найден подтверждённый YouTube-канал.",
            )
            failed += 1
            continue

        metadata = dict(snapshot_record.get("metadata", {}) or {})
        automation = dict(snapshot_record.get("automation", {}) or {})
        try:
            duration = max(0.0, float(snapshot_record.get("durationSeconds") or 0))
        except (TypeError, ValueError):
            duration = 0.0
        ad_policy = dict(snapshot_record.get("adPolicy", {}) or {})
        ad_plan = build_ad_plan(
            duration,
            monetized=bool(snapshot_record.get("monetized")) and bool(ad_policy.get("enabled", True)),
            interval_seconds=max(1, int(ad_policy.get("manualIntervalSeconds", 39) or 39)),
        )
        engagement_plan = build_engagement_plan(
            {
                "id": snapshot_id,
                "channelId": channel_id,
                "videoId": video_id,
                "durationSeconds": duration,
            },
            catalog,
            [],
        )
        video_url = str(execution.get("youtubeVideoUrl") or "").strip() or f"https://www.youtube.com/watch?v={video_id}"
        description = re.sub(r"(?<!\w)#[^\s#]+", "", str(metadata.get("description", ""))).strip()
        community_post = dict(snapshot_record.get("communityPost", {}) or {})
        cta = re.sub(r"(?<!\w)#[^\s#]+", "", str(community_post.get("callToAction", "") or "")).strip()
        post_text = "\n\n".join(value for value in (description, cta, video_url) if value)

        steps_now = dict((settings.youtube_publication_executions.get(snapshot_id, {}) or {}).get("steps", {}) or {})
        task = {
            "videoId": video_id,
            "channelId": channel_id,
            "publishAt": str(snapshot_record.get("requestedPublishAt") or ""),
            "ads": {"status": "done" if str(dict(steps_now.get("ADS", {}) or {}).get("status", "")).upper() in terminal else "pending"},
            "post": {"status": "done" if str(dict(steps_now.get("POST", {}) or {}).get("status", "")).upper() in terminal else "pending"},
            "cards": {"status": "done" if str(dict(steps_now.get("CARDS", {}) or {}).get("status", "")).upper() in terminal else "pending"},
            "endScreen": {"status": "done" if str(dict(steps_now.get("END_SCREEN", {}) or {}).get("status", "")).upper() in terminal else "pending"},
            "postDraft": {"text": post_text, "videoUrl": video_url},
            "plan": {
                "ads": ad_plan,
                "cards": list(engagement_plan.get("cards") or []),
                "endScreen": dict(engagement_plan.get("endScreen") or {}),
            },
        }

        for kind in ("ads", "post", "cards", "end-screen"):
            if kind not in requested_kinds:
                continue
            stage = stage_map[kind]

            policy_key = {"ads": "ads", "post": "post", "cards": "cards", "end-screen": "endScreen"}[kind]
            # The frozen snapshot is authoritative after confirmation. Ads are
            # mandatory for a channel frozen as monetized; other Studio
            # automation follows the operator's per-channel snapshot policy.
            if kind != "ads" and automation.get(policy_key) is False:
                mark_publication_stage_not_required(
                    settings, snapshot_id, stage,
                    f"Этап {kind} выключен в подтверждённых правилах канала.",
                    {"reason": "channel_policy"},
                )
                skipped += 1
                continue
            if kind == "ads" and not bool(snapshot_record.get("monetized")):
                mark_publication_stage_not_required(
                    settings, snapshot_id, stage,
                    "Канал не отмечен как монетизированный.",
                    {"mode": "NONE", "reason": "channel_not_monetized"},
                )
                skipped += 1
                continue
            execution = dict(settings.youtube_publication_executions.get(snapshot_id, {}) or {})
            execution_steps = dict(execution.get("steps", {}) or {})
            stage_state = str(dict(execution_steps.get(stage, {}) or {}).get("status", "PENDING")).upper()
            if stage_state in terminal:
                skipped += 1
                continue
            reupload_state = dict(execution.get("reupload", {}) or {})
            if kind == "post" and reupload_state and not bool(reupload_state.get("scheduleApplied")):
                fail_publication_stage(
                    settings,
                    snapshot_id,
                    "POST",
                    "USER_ACTION_REQUIRED",
                    "Community post не запущен: исходное расписание replacement upload сохранено только для проверки и не применено автоматически.",
                )
                skipped += 1
                continue
            if kind in {"ads", "post", "cards", "end-screen"} and str(dict(execution_steps.get("YOUTUBE_PROCESSING", {}) or {}).get("status", "")).upper() != "SUCCESS":
                skipped += 1
                continue
            if kind == "ads" and not bool(ad_plan.get("monetizationEnabled")):
                mark_publication_stage_not_required(settings, snapshot_id, stage, "Канал не отмечен как монетизированный.",
                                                    {"mode": "NONE"})
                skipped += 1
                continue
            if kind == "post" and not post_text:
                mark_publication_stage_not_required(settings, snapshot_id, stage, "Нет текста для Community post.")
                skipped += 1
                continue
            if kind == "cards" and not list(engagement_plan.get("cards") or []):
                mark_publication_stage_not_required(settings, snapshot_id, stage, "Нет другого публичного ролика для безопасной подсказки.")
                skipped += 1
                continue
            end_screen = dict(engagement_plan.get("endScreen") or {})
            if kind == "end-screen" and str(end_screen.get("status", "")) == "skipped":
                mark_publication_stage_not_required(settings, snapshot_id, stage,
                                                    str(end_screen.get("reason") or "Конечная заставка недоступна."))
                skipped += 1
                continue

            worker_id = f"publication-v2-studio-{kind}-{uuid.uuid4().hex[:8]}"
            try:
                begin_publication_stage(settings, snapshot_id, worker_id, stage)
                save_settings(settings)
                completed = execute_studio_task(
                    task,
                    profile_dir=_youtube_channel_profile_dir(channel_id),
                    youtube_channel_id=str(channel.get("channel_id", "")).strip(),
                    action_kinds={kind},
                )
                if kind not in completed:
                    raise StudioAutomationError(f"Studio не подтвердил этап {kind}.")
                provider_result: dict = {"kind": kind}
                if kind == "ads":
                    actual_ads = dict((task.get("_studioResults") or {}).get("ads") or {})
                    provider_result.update({
                        "mode": str(actual_ads.get("mode", "NONE")),
                        "automaticSlotsEnabled": bool(actual_ads.get("automatic")),
                        "manualSlotsSeconds": list(actual_ads.get("manualSlots") or ad_plan.get("manualSlotsSeconds") or []),
                        "confirmedManualSlotsSeconds": list(actual_ads.get("confirmedManualSlots") or []),
                        "midRollEligible": bool(ad_plan.get("midRollEligible")),
                        "manualMidrollApplicable": bool(actual_ads.get("manualMidrollApplicable")),
                    })
                    if bool(actual_ads.get("manualMidrollApplicable")) and not bool(actual_ads.get("manual")):
                        fail_publication_stage(
                            settings, snapshot_id, stage, "RETRYABLE",
                            "Автоматическая реклама включена, но не все ручные 39-секундные слоты подтверждены.",
                        )
                        current_execution = settings.youtube_publication_executions[snapshot_id]
                        current_ads = dict(current_execution.get("steps", {}).get("ADS", {}) or {})
                        current_ads["providerResult"] = provider_result
                        current_execution["steps"]["ADS"] = current_ads
                        release_execution(settings, snapshot_id, worker_id)
                        save_settings(settings)
                        failed += 1
                        break
                elif kind == "post":
                    provider_result.update({"publishAt": task["publishAt"], "videoUrl": video_url})
                elif kind == "cards":
                    provider_result.update({"count": len(list(engagement_plan.get("cards") or [])),
                                            "cards": list(engagement_plan.get("cards") or [])})
                elif kind == "end-screen":
                    provider_result.update({"startSeconds": end_screen.get("startSeconds"),
                                            "items": list(end_screen.get("items") or [])})
                complete_publication_stage(settings, snapshot_id, worker_id, stage, provider_result)
                save_settings(settings)
                succeeded += 1
            except StudioIdentityVerificationRequired as exc:
                fail_publication_stage(
                    settings, snapshot_id, stage,
                    "STUDIO_IDENTITY_REQUIRED", str(exc),
                )
                release_execution(settings, snapshot_id, worker_id)
                save_settings(settings)
                failed += 1
                break
            except StudioAutomationError as exc:
                fail_publication_stage(settings, snapshot_id, stage, "RETRYABLE", str(exc))
                release_execution(settings, snapshot_id, worker_id)
                save_settings(settings)
                failed += 1
                break
            except _BRIDGE_OPERATION_ERRORS as exc:
                fail_publication_stage(settings, snapshot_id, stage, classify_publication_error(exc), str(exc))
                release_execution(settings, snapshot_id, worker_id)
                save_settings(settings)
                failed += 1
                break

        execution = dict(settings.youtube_publication_executions.get(snapshot_id, {}) or {})
        if str(execution.get("overallStatus", "")).upper() in {"DONE", "SCHEDULED"}:
            persist_publication_receipt(settings, snapshot_id)

    save_settings(settings)
    return {
        **snapshot(),
        "operationResult": {
            "kind": "publication-v2-studio",
            "count": succeeded,
            "failed": failed,
            "skipped": skipped,
            "message": f"Studio-этапов подтверждено: {succeeded}; ошибок: {failed}; пропущено: {skipped}.",
        },
    }


def run_auto_pipeline(payload: dict) -> dict:
    """Run the production chain after the user has manually approved ideas.

    The function deliberately does not call idea generation. Every downstream
    network or paid operation is invoked only through the explicit
    ``Запустить автоэтапы`` button in Electron. Individual stages can be
    disabled in the request for a manual review workflow.
    """
    settings = load_settings()
    settings.auto_montage_enabled = bool(payload.get("enabled", True))
    save_settings(settings)
    if not settings.auto_montage_enabled:
        return {**snapshot(), "pipelineResult": {"status": "manual", "message": "Автоконвейер выключен"}}

    stages = payload.get("stages") if isinstance(payload.get("stages"), dict) else settings.auto_pipeline_stages
    enabled = lambda name: bool(stages.get(name, settings.auto_pipeline_stages.get(name, True)))
    titles, jobs = load_session()
    if not titles:
        raise ValueError("Сначала вручную добавьте одобренные идеи в сценарии")
    completed = {job.request.index for job in jobs if job.state == RunState.DONE and job.result.strip()}
    pending = [index for index in range(len(titles)) if index not in completed]
    if pending and enabled("scenarios"):
        generate_scenarios({"indices": pending, "chatUrl": payload.get("chatUrl", "")})
        titles, jobs = load_session()
        completed = {job.request.index for job in jobs if job.state == RunState.DONE and job.result.strip()}
    if not completed:
        raise ValueError("Нет готовых сценариев: проверьте Chrome-сессии или ключ OpenAI")
    indices = sorted(completed)
    if enabled("covers"):
        transfer_scenarios({"target": "covers", "indices": indices})
        settings = load_settings()
        pending_cover_rows = _select_current_cover_generation_rows(
            settings, {}, lambda item: item.get("status") != "Готово",
        )
        if pending_cover_rows:
            generate_covers({
                "indices": [index for index, _item in pending_cover_rows],
                "productionItemIds": [str(item.get("production_item_id", "")).strip()
                                      for _index, item in pending_cover_rows],
            })
    if enabled("seo"):
        transfer_scenarios({"target": "seo", "indices": indices})
        settings = load_settings()
        pending_seo = [index for index, item in enumerate(settings.seo_queue)
                       if item.get("status") != "Готово"]
        if pending_seo:
            generate_seo({"indices": pending_seo, "chatUrl": payload.get("chatUrl", "")})
    if enabled("voice"):
        transfer_scenarios({"target": "voice", "indices": indices})
        generate_voice({"indices": indices})
    if enabled("montage"):
        settings = load_settings()
        if not settings.footage_folders:
            raise ValueError("Для автомонтажа добавьте папку с футажами и выполните ИИ-индексацию")
        for index in indices:
            voice_path = settings.voice_scenario_outputs.get(str(index + 1), "")
            if not voice_path or not Path(voice_path).is_file():
                continue
            prepared = prepare_montage({"scenarioIndex": index, "aspectRatio": settings.montage_aspect_ratio})
            project_path = prepared.get("preparedProject", {}).get("path", "")
            if project_path:
                render_montage({"projectPath": project_path})
    if enabled("package"):
        package_outputs({})
    return {**snapshot(), "pipelineResult": {"status": "done", "scenarios": len(indices)}}


def generate_media(payload: dict) -> dict:
    settings = load_settings()
    prompt = str(payload.get("prompt", "")).strip()
    operation = str(payload.get("operation", "")).strip()
    media_type = str(payload.get("type", "image"))
    if not prompt or not operation:
        raise ValueError("Введите промпт и выберите модель")
    pool = FastGenPool(_selected_fastgen_keys(settings))
    suffix = "Видео" if media_type == "video" else "Фото"
    output = Path(settings.media_output_folder) / suffix
    paths = pool.generate_media(prompt, output, f"{media_type}-{len(list(output.glob('*'))) + 1:03d}", operation,
                                str(payload.get("aspectRatio", "16:9")), count=max(1, min(6, int(payload.get("count", 1)))))
    return {**snapshot(), "operationResult": {"kind": "media", "count": len(paths), "folder": str(output)}}


def _scenario_length_payload(payload: dict, *, current_target: int = 0,
                             current_minimum: int = 0, current_maximum: int = 0) -> tuple[int, int, int]:
    target = max(0, int(payload.get("targetChars", current_target) or 0))
    minimum = max(0, int(payload.get("allowedMin", current_minimum) or 0))
    maximum = max(0, int(payload.get("allowedMax", current_maximum) or 0))
    if minimum and maximum and minimum > maximum:
        raise ValueError("Минимальная длина сценария больше максимальной")
    return target, minimum, maximum


def save_template(payload: dict) -> dict:
    settings = load_settings()
    template = str(payload.get("template", "")).strip()
    if not template:
        raise ValueError("Введите общий шаблон сценария")
    target, minimum, maximum = _scenario_length_payload(
        payload,
        current_target=settings.scenario_target_chars,
        current_minimum=settings.scenario_allowed_min,
        current_maximum=settings.scenario_allowed_max,
    )
    settings.template = template
    settings.scenario_target_chars = target
    settings.scenario_allowed_min = minimum
    settings.scenario_allowed_max = maximum
    ranges = payload.get("ranges")
    if isinstance(ranges, list):
        settings.prompt_ranges = [{"start": max(1, int(item.get("start", 1))), "end": max(1, int(item.get("end", 1))),
                                   "prompt": str(item.get("prompt", "")), "target_chars": max(0, int(item.get("target_chars", 0) or 0)),
                                   "allowed_min": max(0, int(item.get("allowed_min", 0) or 0)), "allowed_max": max(0, int(item.get("allowed_max", 0) or 0))} for item in ranges if isinstance(item, dict)]
    save_settings(settings)
    return snapshot()


def save_template_preset(payload: dict) -> dict:
    settings = load_settings()
    name = " ".join(str(payload.get("name", "")).split())
    template = str(payload.get("template", "")).strip()
    if not name:
        raise ValueError("Укажите название пресета")
    if not template:
        raise ValueError("Заполните общий промпт перед сохранением пресета")
    target, minimum, maximum = _scenario_length_payload(payload)
    ranges = payload.get("ranges", [])
    safe_ranges = [{"start": max(1, int(item.get("start", 1))), "end": max(1, int(item.get("end", 1))),
                    "prompt": str(item.get("prompt", "")), "target_chars": max(0, int(item.get("target_chars", 0) or 0)),
                    "allowed_min": max(0, int(item.get("allowed_min", 0) or 0)), "allowed_max": max(0, int(item.get("allowed_max", 0) or 0))} for item in ranges if isinstance(item, dict)] if isinstance(ranges, list) else []
    existing = next((item for item in settings.scenario_templates
                     if item.get("topic") == "__newsflow_desktop__" and str(item.get("name", "")).casefold() == name.casefold()), None)
    value = {
        "name": name,
        "topic": "__newsflow_desktop__",
        "template": template,
        "ranges": safe_ranges,
        "target_chars": target,
        "allowed_min": minimum,
        "allowed_max": maximum,
    }
    if existing is None:
        settings.scenario_templates.append(value)
    else:
        existing.update(value)
    settings.template = template
    settings.prompt_ranges = safe_ranges
    settings.scenario_target_chars = target
    settings.scenario_allowed_min = minimum
    settings.scenario_allowed_max = maximum
    save_settings(settings)
    return {**snapshot(), "operationResult": {"kind": "template-preset", "count": 1,
                                                "message": f"Пресет «{name}» сохранён."}}


def delete_template_preset(payload: dict) -> dict:
    settings = load_settings()
    name = " ".join(str(payload.get("name", "")).split())
    before = len(settings.scenario_templates)
    settings.scenario_templates = [item for item in settings.scenario_templates
                                   if not (item.get("topic") == "__newsflow_desktop__"
                                           and str(item.get("name", "")).casefold() == name.casefold())]
    if len(settings.scenario_templates) == before:
        raise ValueError("Пресет не найден")
    save_settings(settings)
    return {**snapshot(), "operationResult": {"kind": "template-preset", "count": 1,
                                                "message": f"Пресет «{name}» удалён."}}


def save_range_preset(payload: dict) -> dict:
    settings = load_settings()
    name = " ".join(str(payload.get("name", "")).split())
    ranges = payload.get("ranges", [])
    if not name:
        raise ValueError("Укажите название пресета диапазонов")
    if not isinstance(ranges, list) or not ranges:
        raise ValueError("Добавьте хотя бы один диапазон для сохранения")
    safe_ranges = [{"start": max(1, int(item.get("start", 1))), "end": max(1, int(item.get("end", 1))),
                    "prompt": str(item.get("prompt", "")), "target_chars": max(0, int(item.get("target_chars", 0) or 0)),
                    "allowed_min": max(0, int(item.get("allowed_min", 0) or 0)), "allowed_max": max(0, int(item.get("allowed_max", 0) or 0))} for item in ranges if isinstance(item, dict)]
    existing = next((item for item in settings.range_templates
                     if item.get("topic") == "__newsflow_desktop__" and str(item.get("name", "")).casefold() == name.casefold()), None)
    value = {"name": name, "topic": "__newsflow_desktop__", "ranges": safe_ranges}
    if existing is None:
        settings.range_templates.append(value)
    else:
        existing.update(value)
    settings.prompt_ranges = safe_ranges
    save_settings(settings)
    return {**snapshot(), "operationResult": {"kind": "range-preset", "count": len(safe_ranges),
                                                "message": f"Набор диапазонов «{name}» сохранён."}}


def delete_range_preset(payload: dict) -> dict:
    settings = load_settings()
    name = " ".join(str(payload.get("name", "")).split())
    before = len(settings.range_templates)
    settings.range_templates = [item for item in settings.range_templates
                                if not (item.get("topic") == "__newsflow_desktop__"
                                        and str(item.get("name", "")).casefold() == name.casefold())]
    if len(settings.range_templates) == before:
        raise ValueError("Пресет диапазонов не найден")
    save_settings(settings)
    return {**snapshot(), "operationResult": {"kind": "range-preset", "count": 1,
                                                "message": f"Набор диапазонов «{name}» удалён."}}


def add_api_key(payload: dict) -> dict:
    kind = str(payload.get("kind", "")).strip()
    label = str(payload.get("label", "")).strip() or "Новый ключ"
    secret = str(payload.get("secret", "")).strip()
    if not secret:
        raise ValueError("Введите API-ключ")
    settings = load_settings()
    if kind == "fastgen":
        settings.cover_api_keys.append(FastGenKey(label, secret, True))
    elif kind == "openai":
        settings.openai_api_keys.append(OpenAIKey(label, secret, True))
    elif kind == "voicer":
        settings.secret_voicer_keys.append(SecretVoicerKey(label, secret, True))
    elif kind == "lumean":
        settings.lumean_api_keys.append(LumeanKey(label, secret, True))
    elif kind == "voicegen":
        settings.voicegen_api_keys.append(VoiceGenKey(label, secret, True))
    elif kind == "wproject":
        settings.wproject_api_keys.append(WProjectKey(label, secret, True))
    elif kind == "youtube":
        settings.youtube_api_key = secret
        settings.youtube_api_enabled = True
    else:
        raise ValueError("Неизвестный тип API-ключа")
    save_settings(settings)
    return snapshot()


def _selected_api_key(payload: dict, *, for_update: bool = False) -> tuple[Settings, str, int, str, str]:
    """Resolve only an explicitly selected, still-current credential."""
    fields = {"fastgen": "cover_api_keys", "openai": "openai_api_keys",
              "voicer": "secret_voicer_keys", "lumean": "lumean_api_keys",
              "voicegen": "voicegen_api_keys", "wproject": "wproject_api_keys",
              "youtube": "youtube_api_key_protected"}
    kind = payload.get("kind")
    index = payload.get("index")
    if not isinstance(kind, str) or kind not in fields or type(index) is not int or index < 0:
        raise ValueError("Ключ не найден")
    settings = load_settings()
    if kind == "youtube":
        if index != 0 or not settings.youtube_api_key:
            raise ValueError("Ключ не найден")
        secret, label = settings.youtube_api_key, "YouTube Data API"
    else:
        entries = getattr(settings, fields[kind])
        if index >= len(entries):
            raise ValueError("Ключ не найден")
        secret, label = entries[index].secret, entries[index].label
    if not payload.get("fingerprint") or payload["fingerprint"] != _api_key_fingerprint(secret):
        raise ValueError("Ключ изменён. Обновите список и откройте его заново.")
    if for_update and payload.get("revision") != _api_key_revision(secret, label):
        raise ValueError("Ключ изменён. Обновите список и откройте его заново.")
    return settings, fields[kind], index, secret, label


def reveal_api_key(payload: dict) -> dict:
    _, _, _, secret, label = _selected_api_key(payload)
    return {"secret": secret, "label": label, "revision": _api_key_revision(secret, label)}


def update_api_key(payload: dict) -> dict:
    settings, field, index, _, old_label = _selected_api_key(payload, for_update=True)
    secret = payload.get("secret")
    if (not isinstance(secret, str) or not secret.strip() or len(secret) > 8192
            or any(ord(char) < 32 or ord(char) == 127 for char in secret)):
        raise ValueError("Введите корректный API-ключ без управляющих символов")
    label = payload.get("label", old_label)
    if not isinstance(label, str) or len(label) > 200:
        raise ValueError("Введите корректное название ключа")
    settings._api_key_replacement = {
        "field": field, "index": index, "revision": payload["revision"],
        "secret": secret.strip(), "label": label.strip() or old_label,
    }
    save_settings(settings)
    return snapshot()


def set_key_active(payload: dict) -> dict:
    settings = load_settings()
    kind = str(payload.get("kind", ""))
    if kind == "youtube":
        if not settings.youtube_api_key:
            raise ValueError("Ключ YouTube Data API не добавлен")
        settings.youtube_api_enabled = bool(payload.get("active", True))
        save_settings(settings)
        return snapshot()
    entries = {"fastgen": settings.cover_api_keys, "openai": settings.openai_api_keys,
               "voicer": settings.secret_voicer_keys, "lumean": settings.lumean_api_keys,
               "voicegen": settings.voicegen_api_keys, "wproject": settings.wproject_api_keys}.get(kind)
    index = int(payload.get("index", -1))
    if entries is None or not 0 <= index < len(entries):
        raise ValueError("Ключ не найден")
    entries[index].active = bool(payload.get("active", True))
    save_settings(settings)
    return snapshot()


def save_api_key_note(payload: dict) -> dict:
    settings = load_settings()
    kind = str(payload.get("kind", "")).strip()
    if kind not in {"fastgen", "openai", "voicer", "lumean", "voicegen", "wproject", "youtube"}:
        raise ValueError("Неизвестный тип API-ключа")
    index = 0 if kind == "youtube" else int(payload.get("index", -1))
    entries = {"fastgen": settings.cover_api_keys, "openai": settings.openai_api_keys,
               "voicer": settings.secret_voicer_keys, "lumean": settings.lumean_api_keys,
               "voicegen": settings.voicegen_api_keys, "wproject": settings.wproject_api_keys}.get(kind)
    if kind == "youtube":
        if not settings.youtube_api_key:
            raise ValueError("Ключ YouTube Data API не добавлен")
    elif entries is None or not 0 <= index < len(entries):
        raise ValueError("Ключ не найден")
    note = " ".join(str(payload.get("note", "")).split())[:500]
    key_id = _api_key_id(kind, index)
    if note:
        settings.api_key_notes[key_id] = note
    else:
        settings.api_key_notes.pop(key_id, None)
    save_settings(settings)
    return snapshot()


def update_voicer_key_settings(payload: dict) -> dict:
    """Persist enabled keys and their per-key parallel stream capacity together."""
    settings = load_settings()
    rows = payload.get("keys")
    if not isinstance(rows, list):
        raise TypeError("Передайте список ключей Secret Voicer")
    for row in rows:
        if not isinstance(row, dict):
            continue
        index = int(row.get("index", -1))
        if not 0 <= index < len(settings.secret_voicer_keys):
            continue
        key = settings.secret_voicer_keys[index]
        key.active = bool(row.get("active", key.active))
        key.streams = max(1, min(20, int(row.get("streams", key.streams))))
    save_settings(settings)
    return snapshot()


def refresh_voicer_balances(payload: dict) -> dict:
    """Explicitly query read-only Secret Voicer account/quota endpoints."""
    settings = load_settings()
    for key in settings.secret_voicer_keys:
        if not key.active or not key.secret.strip():
            continue
        try:
            key.balance = SecretVoicerClient(key.secret).balance_label()
            key.balance_status = "ok"
        except _BRIDGE_OPERATION_ERRORS as exc:
            # Do not invent a balance when this deployment does not expose it.
            key.balance = "—"
            key.balance_status = str(exc)[:220]
    save_settings(settings)
    return snapshot()


